window.EXTRA_DATA_1 = [{"l": 101, "lt": "Extra E01 赫克托到来", "i": 1, "en": "Did you get my message?", "zh": "你收到我的留言/消息了吗？", "b64": "", "src": "extra", "note": "询问对方是否收到留言"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 2, "en": "I told you last night.", "zh": "我昨晚就跟你说过了。", "b64": "", "src": "extra", "note": "提醒对方昨晚提过"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 3, "en": "And don't call me Gigi.", "zh": "还有，别叫我吉吉。", "b64": "", "src": "extra", "note": "纠正称呼/抗议讨厌的外号"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 4, "en": "Who from? What does it say?", "zh": "谁寄来的？信上写了什么？", "b64": "", "src": "extra", "note": "打听信件来历与内容"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 5, "en": "Do you have a bed for me?", "zh": "你们那儿有地方给我睡吗？", "b64": "", "src": "extra", "note": "询问借宿借住"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 6, "en": "He wants to stay here. But what about the rules?", "zh": "他想住在这儿。但合租规矩怎么办？", "b64": "", "src": "extra", "note": "提出合租规矩质询"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 7, "en": "We'll buy your lunch.", "zh": "我们请你吃午饭。", "b64": "", "src": "extra", "note": "经典请客买单表达"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 8, "en": "Would you like a drink?", "zh": "你想喝点什么吗？", "b64": "", "src": "extra", "note": "经典招待问饮品"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 9, "en": "What's she like?", "zh": "她人怎么样？/ 她是个什么样的人？", "b64": "", "src": "extra", "note": "打听某人性格长相"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 10, "en": "Why don't I show you how to do it properly?", "zh": "不如我来教你正确的做法吧？", "b64": "", "src": "extra", "note": "主动示范正确做法"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 11, "en": "Nick, I've told you before, nobody uses my bike.", "zh": "尼克，我之前就跟你说过，谁都不能碰我的单车。", "b64": "", "src": "extra", "note": "重申界限与规矩"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 12, "en": "If you touch my bike again, you are out!", "zh": "要是你再碰我的车，你就给我出去/滚蛋！", "b64": "", "src": "extra", "note": "正式下最后通牒"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 13, "en": "Is that clear?", "zh": "听明白了吗？/ 清楚了吗？", "b64": "", "src": "extra", "note": "问对方听清楚/明白没有"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 14, "en": "No, you don't understand, we only have one bedroom.", "zh": "不，你没搞懂，我们只有一间卧室。", "b64": "", "src": "extra", "note": "解释合租客观困难"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 15, "en": "Well, you can sleep here.", "zh": "行吧，你可以睡这儿。", "b64": "", "src": "extra", "note": "指引借宿位置"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 16, "en": "Just relax, I must go to the bathroom.", "zh": "你先随意放松一下，我去趟洗手间。", "b64": "", "src": "extra", "note": "招呼客人随意/礼貌去洗手间"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 17, "en": "My luggage is downstairs. Could you bring it up?", "zh": "我的行李在楼下，能帮我拿上来吗？", "b64": "", "src": "extra", "note": "请求对方帮忙搬行李"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 18, "en": "I live next door.", "zh": "我就住在隔壁。", "b64": "", "src": "extra", "note": "介绍自己住在隔壁"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 19, "en": "Does she know you are here?", "zh": "她知道你在这儿吗？", "b64": "", "src": "extra", "note": "询问对方知不知情"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 20, "en": "What would you like to eat?", "zh": "你想吃点什么？", "b64": "", "src": "extra", "note": "询问想吃什么"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 21, "en": "The chicks in the apartment opposite have a visitor.", "zh": "对面公寓的姑娘们来了个客人。", "b64": "", "src": "extra", "note": "跟朋友八卦对门邻居"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 22, "en": "See what I mean?", "zh": "明白我的意思了吧？/ 懂我意思了吧？", "b64": "", "src": "extra", "note": "经典口语“懂我意思了吧”"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 23, "en": "Can you cycle 50 kilometers?", "zh": "你能骑行50公里吗？", "b64": "", "src": "extra", "note": "询问运动体能"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 24, "en": "Come on, then show me.", "zh": "来啊，那就展示给我看。", "b64": "", "src": "extra", "note": "激将法“展示给我看”"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 25, "en": "Everything okay?", "zh": "一切都还好吧？/ 还顺利吗？", "b64": "", "src": "extra", "note": "日常关切“还顺利吗”"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 26, "en": "I need a shower.", "zh": "我需要冲个澡。", "b64": "", "src": "extra", "note": "表示需要冲澡"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 27, "en": "Be my guest.", "zh": "请便 / 随便用 / 别客气。", "b64": "", "src": "extra", "note": "经典客套“请便/别客气”"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 28, "en": "What a joke!", "zh": "真是个笑话！/ 太荒谬了！", "b64": "", "src": "extra", "note": "感叹“太荒谬/真是个笑话”"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 29, "en": "You have a spare room.", "zh": "你有间空客房。", "b64": "", "src": "extra", "note": "指出有空余客房"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 30, "en": "No way, not my problem.", "zh": "没门，这可不关我的事。", "b64": "", "src": "extra", "note": "断然拒绝“没门，不关我事”"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 31, "en": "I don't care.", "zh": "我才不管 / 无所谓。", "b64": "", "src": "extra", "note": "表达无所谓/不在乎"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 32, "en": "We have a problem.", "zh": "我们遇到麻烦了 / 我们有个问题。", "b64": "", "src": "extra", "note": "指出遇到麻烦"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 33, "en": "Can I have a word, please?", "zh": "我能跟你私下说句话吗？", "b64": "", "src": "extra", "note": "礼貌请求借一步说话"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 34, "en": "Listen, keep it a secret.", "zh": "听着，一定要保守秘密。", "b64": "", "src": "extra", "note": "嘱咐保守秘密"}, {"l": 101, "lt": "Extra E01 赫克托到来", "i": 35, "en": "What sort of music do you like?", "zh": "你喜欢什么类型的音乐？", "b64": "", "src": "extra", "note": "闲聊询问音乐偏好"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 1, "en": "Hey, is Hector still asleep?", "zh": "嘿，赫克托还在睡觉吗？", "note": "日常询问作息", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 2, "en": "Hector, wakey-wakey. Rise and shine!", "zh": "赫克托，醒醒啦，太阳晒屁股啦！", "note": "地道生动的晨间唤醒俚语", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 3, "en": "I have a cold. — So have I.", "zh": "我感冒了。— 我也感冒了。", "note": "经典日常倒装句型 So have I", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 4, "en": "So let's begin again.", "zh": "那咱们重新开始吧。", "note": "被意外打断后重新开始", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 5, "en": "Please excuse me for a moment.", "zh": "抱歉，请稍等我一下 / 失陪片刻。", "note": "得体礼貌的离席用语", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 6, "en": "Can I tell you something?", "zh": "我能跟你说件事吗？", "note": "开启私密话题/给建议的常用引导句", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 7, "en": "All right, I'm coming as fast as I can.", "zh": "好啦好啦，我已经以最快速度过来了！", "note": "被催促时的地道回应", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 8, "en": "I feel awful. Nothing will make me feel better.", "zh": "我难受极了，现在什么都不能让我好受点。", "note": "描述生病身体不适", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 9, "en": "Can you get that, please?", "zh": "能麻烦你去开下门/接下电话吗？", "note": "生活高频委托 get that", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 10, "en": "The car looks good, so you must look good too.", "zh": "车很帅，所以你也得穿得帅才行。", "note": "表达审美要求与期待", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 11, "en": "You don't look good, but I can help.", "zh": "你现在这身可不怎么样，不过我可以帮你。", "note": "主动提出穿搭改造", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 12, "en": "These clothes are awful. They are so old-fashioned.", "zh": "这些衣服太糟糕了，简直太老土了。", "note": "评价过时穿搭", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 13, "en": "I'll take him shopping.", "zh": "我带他去买衣服吧。", "note": "主动提出陪同购物", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 14, "en": "Hector has asked me what clothes to wear.", "zh": "赫克托问我他该穿什么衣服。", "note": "宾语从句口语运用", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 15, "en": "Don't listen to Nick, listen to me.", "zh": "别听尼克的，听我的。", "note": "提出不同意见", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 16, "en": "You need a designer look.", "zh": "你需要有名师设计/大牌风范的造型。", "note": "时尚词汇 designer look", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 17, "en": "That's not for you.", "zh": "那个风格不适合你。", "note": "表达“不适合你”的极简地道说法", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 18, "en": "I bought Hector a really trendy outfit.", "zh": "我给赫克托买了一套超潮的行头。", "note": "实用词汇 trendy outfit", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 19, "en": "You will look so cool.", "zh": "你穿上肯定帅呆了。", "note": "称赞与外观预期", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 20, "en": "Leave it to me.", "zh": "包在我身上 / 交给我吧。", "note": "超高频地道口语", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 21, "en": "I am the shopkeeper. You are the customer.", "zh": "我是店员，你是顾客。", "note": "角色扮演说明", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 22, "en": "Can I help you, sir? What would you like to buy?", "zh": "先生，需要帮您吗？您想买点什么？", "note": "经典商店服务开场", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 23, "en": "I would like a pair of trousers, please.", "zh": "我想买一条长裤。", "note": "量词搭配 a pair of trousers", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 24, "en": "I think you mean a hat.", "zh": "我想你的意思是帽子吧。", "note": "礼貌纠正口误", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 25, "en": "Try it on!", "zh": "穿上试试看！/ 试穿一下！", "note": "买衣服核心短语", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 26, "en": "I cannot wait for him to try it on.", "zh": "我等不及看他试穿了。", "note": "表达迫不及待", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 27, "en": "What size are you?", "zh": "您穿多大尺码？", "note": "服装店询问尺码核心句", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 28, "en": "I'll have to measure you then.", "zh": "那我就得替你量下尺寸了。", "note": "量身 measure you", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 29, "en": "Arms up, please.", "zh": "请把双臂抬起来。", "note": "量体指令", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 30, "en": "Chest: 112 centimeters. Waist: 82 centimeters.", "zh": "胸围112公分，腰围82公分。", "note": "实用尺寸词汇", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 31, "en": "It's too expensive.", "zh": "这太贵了。", "note": "嫌贵/议价表达", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 32, "en": "A little bit each.", "zh": "我们每人分担买一点。", "note": "日常分工表达", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 33, "en": "I'll do it online later.", "zh": "我晚点在网上买/办就行了。", "note": "现代网购高频句", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 34, "en": "I think Hector has been shopping online.", "zh": "我觉得赫克托刚才在网购了。", "note": "现在完成进行时口语", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 35, "en": "He bought 10 melons instead of 10 lemons.", "zh": "他买了10个甜瓜，本来是要买10个柠檬的。", "note": "介词短语 instead of", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 36, "en": "A dozen is twelve!", "zh": "一打是十二个呀！", "note": "计量单位 a dozen", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 37, "en": "Have you ever been to a supermarket?", "zh": "你以前去过超市吗？", "note": "询问过往经历", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 38, "en": "I will teach you how to shop.", "zh": "我来教你怎么买东西。", "note": "主动指导他人", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 39, "en": "Don't answer the phone. It might be the tarantula.", "zh": "别接电话，可能是母蜘蛛/房东打来的。", "note": "推测情态动词 might", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 40, "en": "Be good. And if you can't be good, be careful.", "zh": "乖一点；要是乖不了，就小心点。", "note": "经典英式幽默告诫", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 41, "en": "You should see them. They are so funny.", "zh": "你真该看看那些衣服，太搞笑了。", "note": "日常分享与感叹", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 42, "en": "So guess what? We're all going shopping for Hector.", "zh": "你猜怎么着？我们都要去帮赫克托买衣服了。", "note": "经典口语引入 guess what", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 43, "en": "I've got something for you.", "zh": "我有东西要给你 / 我给你带了个好东西。", "note": "日常赠送/拿东西给别人", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 44, "en": "Well, he did try.", "zh": "好吧，他确实尽力尝试了。", "note": "口语强调语气 did try", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 45, "en": "Oh, an easy mistake.", "zh": "哎呀，很容易犯的常见小失误。", "note": "安慰别人的口语", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 46, "en": "Here we go again.", "zh": "又来了 / 怎么又来这出。", "note": "极高频日常俚语", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 47, "en": "You can't go out there on your own.", "zh": "你不能自己一个人单独出门去。", "note": "习语 on your own", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 48, "en": "Good luck. You'll need it!", "zh": "祝你好运，你肯定用得上的！", "note": "朋友间开玩笑戏谑", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 49, "en": "Well, don't you look great!", "zh": "哇，你看起来可真帅气！", "note": "否定疑问句表赞美感叹", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 50, "en": "Oh, you are clever, Hector!", "zh": "哎呀，你真聪明/真有本事！", "note": "地道口语夸奖", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 51, "en": "I don't believe you.", "zh": "我才不信你呢。", "note": "日常反驳/不信", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 52, "en": "Silly me! I told you this morning.", "zh": "瞧我这记性！我今天早上才跟你说过的。", "note": "自嘲粗心地道表达 silly me", "b64": "", "src": "extra"}, {"l": 102, "lt": "Extra E02 赫克托去购物", "i": 53, "en": "I'm really thirsty. I need a drink.", "zh": "我渴坏了，我得喝口水。", "note": "日常生理需求表达", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 1, "en": "Make my dream come true.", "zh": "让我的梦想成真吧。", "note": "浪漫期待表达", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 2, "en": "Cindy is so old-fashioned.", "zh": "辛迪的那套健身操太老土了。", "note": "评价过时/落伍", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 3, "en": "I can teach Hector how to exercise.", "zh": "我可以教赫克托怎么锻炼。", "note": "主动提供辅导", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 4, "en": "Touch your toes. Stand straight.", "zh": "双手摸脚趾，身体站直。", "note": "健身动作指令", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 5, "en": "Let's get a drink.", "zh": "咱们去喝点东西吧。", "note": "运动后/闲暇提议", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 6, "en": "After you. — No, you first.", "zh": "你先请。— 不，你先来。", "note": "经典谦让礼貌用语", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 7, "en": "Now, give it to me.", "zh": "好啦，快拿给我吧。", "note": "日常索要物品", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 8, "en": "Annie's been on the internet again to find a boyfriend.", "zh": "安妮又上网去找男朋友了。", "note": "现在完成进行时口语", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 9, "en": "Rocky, the tennis star here. Will you be my ball?", "zh": "我是网球明星洛基，你愿意做我的球吗？", "note": "自恋幽默搭讪", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 10, "en": "Third time lucky.", "zh": "事不过三 / 第三次一定会走运。", "note": "经典英式幸运谚语", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 11, "en": "I'll never get a boyfriend.", "zh": "我肯定永远都找不到男朋友了。", "note": "日常沮丧抱怨", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 12, "en": "It's not what you write, it's how you write it.", "zh": "关键不在于写了什么，而在于你怎么写。", "note": "经典哲理句型", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 13, "en": "I could get a girlfriend on the internet, no problem.", "zh": "我在网上找女朋友轻而易举，小菜一碟。", "note": "吹嘘自信表达", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 14, "en": "I bet you could not.", "zh": "我敢打赌你肯定不行。", "note": "日常打赌反驳", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 15, "en": "What would you write?", "zh": "要是你，你会写些什么？", "note": "虚拟假设提问", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 16, "en": "I'm six foot tall.", "zh": "我身高一米八三（六英尺）。", "note": "英美身高表达", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 17, "en": "See you later, boys.", "zh": "回头见啦，小伙子们。", "note": "轻松告别", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 18, "en": "No problem.", "zh": "没问题 / 包在我身上。", "note": "超高频日常口语", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 19, "en": "Will you spray my plant for me, please?", "zh": "能麻烦你帮我给植物喷点水吗？", "note": "客气委托他人", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 20, "en": "The spray is in the bathroom.", "zh": "喷雾器在浴室里。", "note": "指明物品位置", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 21, "en": "Never mind.", "zh": "没关系 / 算了，别放在心上。", "note": "安慰与宽慰", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 22, "en": "I decided to help him with his exercises instead.", "zh": "所以我决定亲自帮他做健身运动。", "note": "短语 help with / instead", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 23, "en": "I had three strange replies.", "zh": "我收到了三条奇奇怪怪的回复。", "note": "描述收到消息", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 24, "en": "It's so easy to find a girlfriend on the internet.", "zh": "在网上找女朋友实在太容易了。", "note": "形容词+不定式结构", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 25, "en": "How do guys get girlfriends?", "zh": "男生们到底怎么追女朋友？", "note": "生活疑问句", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 26, "en": "You have had girlfriends. — Yeah, loads. Hundreds.", "zh": "你谈过女朋友。— 对啊，超多，几百个。", "note": "口语量词 loads", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 27, "en": "So, I know what girls like.", "zh": "所以，我非常清楚女孩子喜欢什么。", "note": "经验自信断言", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 28, "en": "They like fast cars. They like money. They like dancing.", "zh": "她们喜欢跑车，喜欢钞票，还喜欢跳舞。", "note": "典型排比列举", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 29, "en": "Oh, I love dancing!", "zh": "噢，我最喜欢跳舞了！", "note": "表达强烈喜好", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 30, "en": "Leave it to me, my friend. I have a plan.", "zh": "交给我吧哥们儿，我心里有数/有计划。", "note": "高频打气承诺", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 31, "en": "Let's go out and celebrate.", "zh": "咱们出去好好庆祝一番吧。", "note": "提议庆祝", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 32, "en": "It smells like a perfume.", "zh": "这闻起来像是一股香水味。", "note": "感官系动词用法", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 33, "en": "The washing's done.", "zh": "衣服洗完烘干了。", "note": "家务完成表达", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 34, "en": "What's the problem? — This is the problem.", "zh": "出什么问题了？— 这就是问题所在！", "note": "面对突发麻烦", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 35, "en": "What is it now?", "zh": "又怎么啦？/ 这又是哪出？", "note": "烦躁无奈高频句", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 36, "en": "We have 633 messages.", "zh": "我们收到了633条未读留言！", "note": "震惊消息数量", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 37, "en": "Okay, one moment.", "zh": "好，稍等一下。", "note": "日常缓冲用语", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 38, "en": "I smell a rat.", "zh": "我闻到了阴谋的气味 / 事有蹊跷。", "note": "地道英语谚语", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 39, "en": "I think I know who is responsible.", "zh": "我想我知道是谁惹的祸了。", "note": "追查责任人", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 40, "en": "What a joke!", "zh": "真是天大的笑话！/ 太荒唐了！", "note": "日常强烈感叹", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 41, "en": "Let's go to the cyber cafe.", "zh": "走，咱们去网吧看看。", "note": "提议前往某处", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 42, "en": "When we finish the show, shall we meet?", "zh": "等我们演完出，见个面好吗？", "note": "礼貌邀约时机", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 43, "en": "Your apartment at 10 p.m. Is that okay?", "zh": "晚上10点在你们公寓，可以吗？", "note": "商定约会地点", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 44, "en": "Wait a minute. That's just three hours.", "zh": "等一下，那现在就只剩三小时了！", "note": "紧迫时间感叹", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 45, "en": "What am I going to wear?", "zh": "我该穿什么衣服赴约啊？", "note": "出门前经典纠结", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 46, "en": "It's terrible news.", "zh": "这可真是个天大的坏消息。", "note": "传递坏消息", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 47, "en": "Bridget was not pleased.", "zh": "布里吉特脸色可不太好看 / 很不高兴。", "note": "含蓄表达不满", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 48, "en": "Wish us luck!", "zh": "祝我们俩好运吧！", "note": "高频求好运祝福", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 49, "en": "What should I say? — It's easy, relax.", "zh": "我该说什么好？— 很简单，放轻松。", "note": "请教与安抚", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 50, "en": "We need a script. Try this.", "zh": "我们需要一份台词本。试试这句！", "note": "出谋划策", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 51, "en": "Your eyes are blue, like the ocean.", "zh": "你的双眼湛蓝深邃，宛如大海。", "note": "经典浪漫赞美", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 52, "en": "Your hair is so soft.", "zh": "你的头发好柔软。", "note": "细节夸赞", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 53, "en": "We thought you were dancers.", "zh": "我们还以为你们是伴舞演员呢。", "note": "表达误会认知", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 54, "en": "Are you a millionaire?", "zh": "你真的是百万富翁吗？", "note": "直接质问", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 55, "en": "A trick to get girlfriends, very funny.", "zh": "耍这种花招骗女孩子，真是太搞笑了。", "note": "当面拆穿把戏", "b64": "", "src": "extra"}, {"l": 103, "lt": "Extra E03 赫克托约会记", "i": 56, "en": "Don't miss it.", "zh": "精彩内容，切勿错过！", "note": "剧集预告高频句", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 1, "en": "What on earth are you doing? Are you crazy?", "zh": "你到底在搞什么鬼？你疯了吗？", "note": "强烈质问与情绪表达", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 2, "en": "Perhaps some cornflakes instead.", "zh": "要不咱们还是吃点玉米片吧。", "note": "退而求其次地道建议", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 3, "en": "What are you doing on our computer anyway?", "zh": "话说回来，你在我们电脑上干嘛呢？", "note": "日常转移话题询问", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 4, "en": "The coolest stuntman in the world.", "zh": "全世界最帅气的特技演员。", "note": "趣味夸大词汇 stuntman", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 5, "en": "I got the job on the internet.", "zh": "我在网上找到了这份工作。", "note": "求职日常表达", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 6, "en": "I'm waiting for confirmation.", "zh": "我正在等对方的确认通知。", "note": "职场高频表达 confirmation", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 7, "en": "I'd love to have a dress like that.", "zh": "我好想拥有那样一条裙子啊。", "note": "愿望表达 would love to", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 8, "en": "It would really suit me.", "zh": "穿在我身上肯定特别合适。", "note": "表达“适合某人” suit me", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 9, "en": "It's too expensive for me.", "zh": "这对我来说太贵了。", "note": "嫌贵自嘲", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 10, "en": "We need more money.", "zh": "我们需要更多钱。", "note": "日常感叹需求", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 11, "en": "I have something to tell you.", "zh": "我有件事情要告诉你们。", "note": "开启重要谈话", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 12, "en": "Keep it a secret.", "zh": "一定要保密哦。", "note": "保守秘密", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 13, "en": "I am going to look for a job.", "zh": "我准备去找一份工作。", "note": "打算找工作", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 14, "en": "That's a great idea, Hector.", "zh": "这个主意太棒了，赫克托。", "note": "夸赞建议", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 15, "en": "We can look for a job on the internet.", "zh": "我们可以在网上找找看工作。", "note": "日常提议", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 16, "en": "Job vacancies. Let's see.", "zh": "招聘职位空缺。让我们瞧瞧。", "note": "求职核心词 vacancy", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 17, "en": "What about Hector as a waiter?", "zh": "让赫克托去当服务员怎么样？", "note": "征求意见句型 What about", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 18, "en": "But I don't know how.", "zh": "可是我不知道怎么做。", "note": "表达不会/无经验", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 19, "en": "Don't worry. I will teach you.", "zh": "别担心，我会教你的。", "note": "主动安抚与指导", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 20, "en": "Who is Howard? — Bridget's boss.", "zh": "霍华德是谁？— 布里吉特的老板。", "note": "日常人物询问", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 21, "en": "He might offer me a promotion.", "zh": "他可能会给我升职呢！", "note": "职场升职 promotion", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 22, "en": "What shall I wear? I have nothing to wear.", "zh": "我该穿什么呀？我简直没衣服穿了！", "note": "女生出门经典抱怨", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 23, "en": "I have an idea.", "zh": "我有个主意！", "note": "灵光一闪", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 24, "en": "Why don't you eat here?", "zh": "你们为什么不在家里吃呢？", "note": "提出替代建议", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 25, "en": "I could cook for you. — Definitely not!", "zh": "我可以帮你们做饭。— 绝对不行！", "note": "坚决拒绝 definitely not", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 26, "en": "I could be your waiter.", "zh": "我可以来当你们的服务生。", "note": "自告奋勇", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 27, "en": "Be serious!", "zh": "严肃点！别闹了！", "note": "提醒对方认真", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 28, "en": "We will help you get your promotion.", "zh": "我们会帮你拿到升职的！", "note": "鼓励支持朋友", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 29, "en": "Leave it to us.", "zh": "包在我们身上！", "note": "打包票表达", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 30, "en": "What can he do?", "zh": "他能干些什么呢？", "note": "能力询问", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 31, "en": "You must set the table.", "zh": "你得把餐桌布置好摆好餐具。", "note": "家务/餐饮短语 set the table", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 32, "en": "The table is too small.", "zh": "这张桌子太小了。", "note": "日常陈述", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 33, "en": "This is set for 12 courses!", "zh": "你这餐具摆法是准备吃12道大餐啊！", "note": "西餐常识 12 courses", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 34, "en": "Where would you like to sit?", "zh": "请问您想坐在哪儿？", "note": "餐厅领位常用语", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 35, "en": "What have you got today?", "zh": "你们今天有什么菜色/特色？", "note": "餐厅点餐常用问句", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 36, "en": "Today, as dish of the day, I have a delicious hot dog.", "zh": "今天的主推特色菜，我们有美味热狗。", "note": "餐饮常用语 dish of the day", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 37, "en": "Hector's cafe is now closed.", "zh": "赫克托的咖啡馆现在打烊啦。", "note": "打烊口语", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 38, "en": "I'll get it.", "zh": "我去开门 / 我去接电话。", "note": "门铃响超高频口语", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 39, "en": "For beautiful Bridget. It must be Howard.", "zh": "送给美丽的布里吉特。一定是霍华德送的。", "note": "推测情态动词 must be", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 40, "en": "Thank you, Howard.", "zh": "谢谢你，霍华德。", "note": "表达感谢", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 41, "en": "Please come in. You look divine.", "zh": "请进，你看起来美若天仙！", "note": "热情赞赏 divine", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 42, "en": "The dresses are exquisite. It's a privilege.", "zh": "这几件裙子真是精美绝伦。这是我的荣幸。", "note": "上流奉承词 exquisite / privilege", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 43, "en": "My parents own two million cows.", "zh": "我父母家里有两百万头牛。", "note": "低调凡尔赛", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 44, "en": "Dinner is served.", "zh": "晚餐准备好了，请用餐。", "note": "地道西餐开席用语", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 45, "en": "Where did you find him?", "zh": "你打哪儿找到这位活宝的？", "note": "戏谑询问", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 46, "en": "I want hot coffee. — Then you will have hot coffee.", "zh": "我要热咖啡。— 那就如你所愿给你热咖啡！", "note": "怒气回应", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 47, "en": "Don't you dare talk to my friend like that!", "zh": "你竟敢这么跟我朋友说话！", "note": "经典霸气护友", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 48, "en": "You can keep your job, you creep!", "zh": "留着你那破工作自己干吧，你这个讨厌鬼！", "note": "帅气辞职反击", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 49, "en": "I will not spend money on you.", "zh": "我才不会为你花一分钱呢。", "note": "冷酷拒绝", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 50, "en": "Where did you get the money?", "zh": "你从哪儿弄来这么多钱的？", "note": "追问资金来源", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 51, "en": "Let's go clubbing! Come on!", "zh": "走，咱们去酒吧夜店蹦迪！快来！", "note": "年轻人口语 clubbing", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 52, "en": "Money is not everything.", "zh": "金钱并不是一切。", "note": "经典人生哲理", "b64": "", "src": "extra"}, {"l": 104, "lt": "Extra E04 赫克托找工作", "i": 53, "en": "Hop on. I'll give you a lift.", "zh": "跳上车吧，我载你一程！", "note": "超高频日常口语顺风车", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 1, "en": "I'm sorry, but I think you have the wrong number.", "zh": "抱歉，我想你打错电话了。", "note": "接错电话标准礼貌回应", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 2, "en": "What a stupid name!", "zh": "多蠢的名字啊！/ 真是个傻名字！", "note": "日常吐槽名字", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 3, "en": "How did you know it was us? — Lucky guess.", "zh": "你怎么知道是我们？— 瞎猜撞大运的。", "note": "经典幸运猜测", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 4, "en": "This apartment is very busy.", "zh": "这间公寓简直人来人往太忙碌了。", "note": "日常抱怨生活状态", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 5, "en": "Who do you think I am? Your secretary?", "zh": "你当我是谁？你的秘书吗？", "note": "经典反驳质问", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 6, "en": "I never have any privacy.", "zh": "我一点私人空间/隐私都没有。", "note": "抱怨失去私人空间", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 7, "en": "They cut off my telephone. — That's not my problem.", "zh": "他们把我电话停机了。— 那可不关我的事。", "note": "高频日常交锋", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 8, "en": "You should pay your bills.", "zh": "你早该把账单付清了。", "note": "生活常识提醒", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 9, "en": "Please knock on the door. Now I want to be alone.", "zh": "请敲门进屋。现在我想一个人静静。", "note": "礼貌下逐客令", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 10, "en": "That went well. — What's wrong with her?", "zh": "聊得真‘顺利’。— 她这是怎么啦？", "note": "反讽与询问", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 11, "en": "What's on television?", "zh": "电视上在播什么节目？", "note": "看电视常用语", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 12, "en": "I've got the part!", "zh": "我拿到这个角色了！/ 我试镜成功了！", "note": "演员行话试镜成功", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 13, "en": "Wow, man. That is great.", "zh": "哇塞哥们儿，太棒了！", "note": "为朋友高兴", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 14, "en": "Ladies and gentlemen, a star is born!", "zh": "女士们先生们，一颗巨星诞生了！", "note": "经典宣告台词", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 15, "en": "Today London, tomorrow Hollywood.", "zh": "今天征服伦敦，明天进军好莱坞！", "note": "豪言壮语", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 16, "en": "And of course, my adorable girlfriend.", "zh": "当然还有，我那可爱迷人的女朋友。", "note": "甜言蜜语 adorable", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 17, "en": "Wonderful news, Bridget. Nick is going to be on television.", "zh": "天大的好消息，布里吉特！尼克要上电视了！", "note": "分享喜讯", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 18, "en": "See you at the Oscars!", "zh": "咱们奥斯卡颁奖典礼见！", "note": "幽默告别", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 19, "en": "You watch too many adverts.", "zh": "你看了太多广告了。", "note": "吐槽沉迷广告 advert", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 20, "en": "All you have to do is tell me which plate is better.", "zh": "你唯一要做的就是告诉我哪个更好。", "note": "全神贯注指令", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 21, "en": "Well, they both smell great.", "zh": "嗯……闻起来都特别香。", "note": "评价气味", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 22, "en": "Oh, you are sweet.", "zh": "哎呀，你人真体贴/真好。", "note": "地道夸人 sweet", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 23, "en": "What a stupid name!", "zh": "这名字真够蠢的！", "note": "嫌弃表达", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 24, "en": "Guess what? I've got the part!", "zh": "你猜怎么着？我拿到角色了！", "note": "惊喜分享", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 25, "en": "I didn't realize.", "zh": "我之前完全没意识到 / 没想到。", "note": "口语高频 didn't realize", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 26, "en": "I had some words, but they were cut.", "zh": "我本来还有几句台词的，但被剪掉了。", "note": "演员经历自嘲", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 27, "en": "When I'm a star, I will not forget you, my friend.", "zh": "等我成了大明星，绝不会忘记你这个朋友的。", "note": "兄弟情深承诺", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 28, "en": "The way to the heart is through the stomach.", "zh": "要想抓住一个人的心，先要抓住TA的胃。", "note": "经典英语谚语", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 29, "en": "What does that mean?", "zh": "那是代表什么意思？", "note": "高频询问含义", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 30, "en": "If you want a girlfriend, cook for her.", "zh": "如果你想找女朋友，就亲自下厨给她做顿饭。", "note": "恋爱实用建议", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 31, "en": "I want to learn how to cook.", "zh": "我想学会怎么做饭。", "note": "学习意愿表达", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 32, "en": "Have you seen my red t-shirt anywhere?", "zh": "你们有在哪儿看见我的红T恤吗？", "note": "日常找寻衣物", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 33, "en": "Do you know where Nick is? — No, we've just arrived.", "zh": "你们知道尼克在哪儿吗？— 不知道，我们刚到。", "note": "日常行踪询问", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 34, "en": "Look, talk to my agent, Bridget.", "zh": "听着，找我的经纪人布里吉特谈吧。", "note": "大牌明星腔调 agent", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 35, "en": "What are you working on now?", "zh": "你最近在忙什么项目/工作？", "note": "职场寒暄工作", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 36, "en": "Yeah, you can laugh.", "zh": "行，你们就尽管笑吧。", "note": "被嘲笑时的自嘲", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 37, "en": "Nick from next door has star quality.", "zh": "隔壁的尼克可是天生自带明星相。", "note": "赞美巨星潜质 star quality", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 38, "en": "Excuse me. I must learn my lines.", "zh": "失陪了，我得去背台词了。", "note": "地道演员短语 learn lines", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 39, "en": "First, take some chocolate and melt it over hot water.", "zh": "首先，取一些巧克力，隔热水融化。", "note": "烘焙做菜核心步骤", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 40, "en": "Separate the yolk from the white.", "zh": "把蛋黄和蛋清分开。", "note": "烘焙分蛋专业表达", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 41, "en": "Mix the yolk and the chocolate. Add the butter.", "zh": "把蛋黄和巧克力搅拌均匀，然后加入黄油。", "note": "烘焙烹饪指令", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 42, "en": "I love whisking, don't you?", "zh": "我最喜欢打发蛋白/蛋液了，你呢？", "note": "实用动词 whisking", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 43, "en": "Finally, add the whites to the chocolate and put it in the fridge.", "zh": "最后，把打发的蛋白拌入巧克力中，放进冰箱。", "note": "甜品制作收尾", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 44, "en": "Hector, who's the lucky lady?", "zh": "赫克托，谁是那位幸运的女士呀？", "note": "八卦恋情高频句", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 45, "en": "And here is the weather.", "zh": "下面为您播报天气预报。", "note": "天气预报播音员常用语", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 46, "en": "In the south, it will be sunny.", "zh": "南部地区将会是晴天。", "note": "天气播报 sunny", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 47, "en": "And in the west, it will be windy.", "zh": "西部地区将会刮风。", "note": "天气播报 windy", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 48, "en": "And in the east, it will rain. So don't forget your umbrella.", "zh": "东部地区会有雨，所以别忘了带雨伞哦。", "note": "经典天气关怀提醒", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 49, "en": "Close your eyes. Are you ready?", "zh": "闭上眼睛，准备好了吗？", "note": "制造惊喜氛围", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 50, "en": "The taste of chocolate is so smooth.", "zh": "巧克力的口感如此丝滑香浓。", "note": "甜点口感描绘 smooth", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 51, "en": "Hector, that was so much fun! I love doing adverts.", "zh": "赫克托，太好玩了！我好喜欢拍广告！", "note": "表达乐趣 fun", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 52, "en": "I'm glad you like it.", "zh": "很高兴你喜欢！", "note": "客气回应称赞", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 53, "en": "You must be very tired now. — Yeah, I am.", "zh": "你现在一定累坏了吧。— 是的，真累死我了。", "note": "关心对方疲惫", "b64": "", "src": "extra"}, {"l": 105, "lt": "Extra E05 明星诞生", "i": 54, "en": "Why did you run? — Because I was chased!", "zh": "你为什么一路跑回来？— 因为我被人在后面追啊！", "note": "搞笑落荒而逃", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 1, "en": "I know how to keep calm: Yoga.", "zh": "我知道怎么保持冷静：练瑜伽。", "note": "生活减压方式", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 2, "en": "I am going shopping. Do you need anything?", "zh": "我要去买东西，你需要带什么吗？", "note": "外出帮带东西常用语", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 3, "en": "Could you get my dress from the dry cleaners, please?", "zh": "能麻烦你帮我去干洗店取下裙子吗？", "note": "干洗店取衣委托", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 4, "en": "The blue ticket is on the board.", "zh": "蓝色的取衣小票在留言板上。", "note": "小票凭证 ticket", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 5, "en": "See you later, Bridget.", "zh": "回头见，布里吉特。", "note": "日常告别", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 6, "en": "Where are you going? — I am going shopping.", "zh": "你要去哪儿？— 我要去购物。", "note": "去向日常问答", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 7, "en": "I need a pen! Paper!", "zh": "我需要一支笔！纸！", "note": "紧急记录电话", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 8, "en": "Today, I met a girl called Emily.", "zh": "今天我遇到一个叫艾米莉的女孩。", "note": "日常邂逅分享", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 9, "en": "She is crazy about me.", "zh": "她对我着迷得不行！", "note": "习语 crazy about me", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 10, "en": "Where did you meet her?", "zh": "你是在哪儿碰到她的？", "note": "追问相遇地点", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 11, "en": "At the traffic lights.", "zh": "在红绿灯路口。", "note": "高频地点交通词", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 12, "en": "Maybe she has a friend or a sister.", "zh": "说不定她有个闺蜜或者姐妹呢。", "note": "期待牵线搭桥", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 13, "en": "It's my lucky day!", "zh": "今天是我的幸运日！", "note": "极高频日常感叹", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 14, "en": "I'm a bit busy. Can I call you back?", "zh": "我有点忙，稍后回你电话好吗？", "note": "电话礼貌推迟", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 15, "en": "From now on, it will be a life of luxury.", "zh": "从今以后，那就是奢华的人生了！", "note": "美好幻想 from now on", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 16, "en": "Designer clothes, exotic holidays.", "zh": "名牌服饰，异国度假！", "note": "奢华生活词汇", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 17, "en": "Luxury homes, the very best restaurants.", "zh": "豪华豪宅，顶级高档餐厅！", "note": "高档生活体验", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 18, "en": "No more work! No more buses!", "zh": "再也不用上班了！再也不用挤公交了！", "note": "摆脱打工人命运", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 19, "en": "I'll call now and resign.", "zh": "我现在就打电话辞职！", "note": "职场辞职 resign", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 20, "en": "Bridget, I resign. I quit your job!", "zh": "我辞职了！我不干了！", "note": "霸气辞职 quit", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 21, "en": "Bridget is the boss!", "zh": "布里吉特自己当老板！", "note": "志得意满", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 22, "en": "Now, I'll just get my lucky little ticket.", "zh": "现在，我来拿上我那张幸运小彩票。", "note": "拿取凭证", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 23, "en": "The good news is, Bridget has won the lottery.", "zh": "好消息是，布里吉特中了彩票大奖。", "note": "经典好消息开场", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 24, "en": "The bad news is, her winning lottery ticket has disappeared.", "zh": "坏消息是，她的中奖彩票不翼而飞了！", "note": "剧情转折", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 25, "en": "My lottery ticket has disappeared!", "zh": "我的彩票不见了！", "note": "惊慌失措", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 26, "en": "Your dress, Bridget. I forgot. Sorry.", "zh": "你的裙子，布里吉特……我忘了取，对不起。", "note": "忘办事道歉", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 27, "en": "You have the wrong ticket.", "zh": "你拿错小票了！", "note": "指出错误", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 28, "en": "Now, give it to me.", "zh": "现在，快拿给我！", "note": "命令语气", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 29, "en": "I have lost the ticket.", "zh": "我把票给弄丢了。", "note": "坦白失误", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 30, "en": "You can't have lost the ticket!", "zh": "你不可能把票弄丢的！", "note": "情态动词推测 can't have", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 31, "en": "The ticket you took was not the dry cleaning ticket.", "zh": "你从板上拿走的根本不是干洗票！", "note": "定语从句运用", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 32, "en": "Hector, where have you been?", "zh": "赫克托，你今天都去哪儿了？", "note": "现在完成时追问行踪", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 33, "en": "First we went to Leo's cafe.", "zh": "首先我们去了利奥咖啡馆。", "note": "时间叙事顺序", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 34, "en": "And then we went to the CD shop.", "zh": "然后我们去了CD唱片店。", "note": "叙述行程", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 35, "en": "And then we went to the motorbike showroom.", "zh": "接着我们去了摩托车展厅。", "note": "展厅词汇 showroom", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 36, "en": "Don't come back until you have found it, okay?", "zh": "没找到之前，你们两个别给我回来，听懂了吗？", "note": "not... until 经典句型", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 37, "en": "The ticket must be claimed by ten o'clock tonight.", "zh": "彩票必须在今晚十点前兑奖！", "note": "被动语态与截止期限", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 38, "en": "Now get going!", "zh": "现在立刻给我出发去找！", "note": "催促行动口语", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 39, "en": "There is trouble at home. — You can say that again!", "zh": "家里出大乱子了。— 谁说不是呢！太赞同了！", "note": "经典习语 You can say that again", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 40, "en": "Emily might return.", "zh": "艾米莉说不定还会回来呢。", "note": "推测情态动词 might", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 41, "en": "What shall I do? — Look for the ticket, of course!", "zh": "那我该干嘛？— 当然是去找彩票啊！", "note": "日常对话 of course", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 42, "en": "What shall I say? — I am the shopkeeper.", "zh": "那我该怎么说？— 我是店主，你来演。", "note": "角色扮演模拟", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 43, "en": "I have lost my winning lottery ticket.", "zh": "我弄丢了我的中奖彩票。", "note": "大实话", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 44, "en": "They will keep the money. They will hide it.", "zh": "他们会把钱私吞藏起来的。", "note": "推测他人行为", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 45, "en": "Someone who can search the rubbish bins: a dustman!", "zh": "一个可以翻垃圾桶的人：清洁工！", "note": "日常职业词汇 dustman", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 46, "en": "Great idea, Nick!", "zh": "好主意，尼克！", "note": "日常赞赏", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 47, "en": "Have you found the ticket? — No, not yet.", "zh": "找到彩票了吗？— 还没有呢。", "note": "日常核实进度", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 48, "en": "The bad news is I didn't find her.", "zh": "坏消息是我没找到她。", "note": "交待结果", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 49, "en": "I made 50 pounds cleaning windscreens.", "zh": "我擦汽车挡风玻璃赚了50英镑！", "note": "勤工俭学词汇 windscreen", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 50, "en": "Give it to me! It's my lottery ticket!", "zh": "快给我！这是我的彩票！", "note": "失而复得狂喜", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 51, "en": "Isn't it exciting?", "zh": "难道这不令人兴奋吗？", "note": "否定反问", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 52, "en": "What were you doing while watching the lottery? — My yoga!", "zh": "你看摇奖时在干嘛？— 我在练瑜伽！", "note": "过去进行时与揭开真相", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 53, "en": "Which position? — Inverted headstand!", "zh": "哪个体式？— 倒立！", "note": "揭晓真相看倒了", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 54, "en": "Well, it cannot get any worse. — Yes, it can!", "zh": "好吧，事情不可能更糟了。— 不，还能更糟！", "note": "经典黑色幽默反转", "b64": "", "src": "extra"}, {"l": 106, "lt": "Extra E06 查理立大功", "i": 55, "en": "We must get that tape back!", "zh": "我们必须把电话录音磁带偷拿回来！", "note": "拯救职场危机", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 1, "en": "Women love doctors. Bridget can't resist me.", "zh": "女孩子最崇拜医生了，布里吉特抗拒不了我。", "note": "迷之自信幽默", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 2, "en": "See you soon, mummy. Love you lots.", "zh": "待会儿见，老妈，超爱你哦。", "note": "温馨亲切家常告别", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 3, "en": "Tell me where it hurts.", "zh": "告诉我你哪里不舒服/哪里疼？", "note": "看病问诊经典台词", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 4, "en": "Doesn't Nick look good as a doctor?", "zh": "尼克扮成医生是不是帅呆了？", "note": "肯定反问赞叹", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 5, "en": "Now you must excuse me. I must do my makeup.", "zh": "抱歉失陪一下，我得去补个妆了。", "note": "离席与补妆礼仪", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 6, "en": "My twin sister Chrissy has arrived from Australia.", "zh": "我的双胞胎妹妹克丽茜从澳大利亚来了。", "note": "介绍双胞胎", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 7, "en": "She lost her luggage, so she borrowed my clothes.", "zh": "她的行李丢了，所以借穿了我的衣服。", "note": "解释穿衣原因", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 8, "en": "Bridget is in a really strange mood today.", "zh": "布里吉特今天的心情真古怪。", "note": "情绪变化描述 strange mood", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 9, "en": "I am confused.", "zh": "我彻底被搞糊涂了 / 我好困惑。", "note": "极高频日常口语 confused", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 10, "en": "I wonder what Bridget was like when she was younger.", "zh": "真好奇布里吉特小时候是什么样子的。", "note": "好奇过去 I wonder what... was like", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 11, "en": "I must continue rehearsing.", "zh": "我得抓紧继续排练了。", "note": "排练 rehearse", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 12, "en": "Are you two dating?", "zh": "你们俩正在谈恋爱约会吗？", "note": "八卦恋情高频句", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 13, "en": "You can tell me. It's not a problem.", "zh": "你可以跟我说的，完全没关系。", "note": "鼓励倾诉心事", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 14, "en": "I really like Annie, but she doesn't notice me.", "zh": "我其实很喜欢安妮，但她从不注意我。", "note": "暗恋告白", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 15, "en": "Well, ask her on a date!", "zh": "那你就主动约她出去啊！", "note": "极高频恋爱建议", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 16, "en": "Should I?", "zh": "我真的该这么做吗？/ 真的行吗？", "note": "犹豫询问建议", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 17, "en": "When I was at the airport today, I found this magazine.", "zh": "我今天在机场翻到这本杂志。", "note": "日常叙事铺垫", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 18, "en": "Are you this rich boy, Hector?", "zh": "这个阔少就是你吗，赫克托？", "note": "直接质问身份", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 19, "en": "Please don't tell Annie.", "zh": "请千万不要告诉安妮。", "note": "保守秘密", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 20, "en": "Don't worry. Your secret is safe with me.", "zh": "放心吧，你的秘密在我这儿绝对守口如瓶。", "note": "地道保密承诺 safe with me", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 21, "en": "Bridget is in a really good mood today.", "zh": "布里吉特今天心情可真好啊！", "note": "好心情描述", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 22, "en": "You're so strong!", "zh": "你力气好大，真强壮！", "note": "夸奖男生力气大", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 23, "en": "I need a drink. Would you like one? — Yes, please.", "zh": "我想喝点水，你来一杯吗？— 好的，谢谢。", "note": "饮品主动邀约", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 24, "en": "In your dreams, Nick!", "zh": "做你的美梦去吧，尼克！", "note": "经典无情拒绝 In your dreams", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 25, "en": "Who moved my bike?!", "zh": "谁动了我的单车？！", "note": "暴怒质问", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 26, "en": "We'll move it back then, if you're strong enough!", "zh": "要是你力气够大，就自己把它搬回去！", "note": "日常拌嘴挑衅", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 27, "en": "Dr. Romero, at your service.", "zh": "罗梅罗医生，随时为您效劳。", "note": "效劳礼貌口语", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 28, "en": "It's like two different people!", "zh": "她简直就像是两个完全不同的人！", "note": "困惑反差感嘆", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 29, "en": "First she asked me to move it, then she told me to put it back!", "zh": "她先叫我搬开，一分钟后又让我放回去！", "note": "抓狂吐槽", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 30, "en": "I have something to ask you.", "zh": "我有件事情想问你。", "note": "郑重开场", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 31, "en": "The thing is...", "zh": "事情是这样的……/ 其实吧……", "note": "支支吾吾口语", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 32, "en": "Would you like to come to the cinema tomorrow night with me?", "zh": "你明晚愿意跟我一起去看电影吗？", "note": "经典正式约会邀请", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 33, "en": "Oh, well, I'd like to!", "zh": "哇，好啊，我很乐意去！", "note": "欣喜接受邀约", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 34, "en": "See you then!", "zh": "那咱们明晚见！", "note": "约定时间告别", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 35, "en": "Have a great time!", "zh": "祝你们玩得开心！", "note": "真诚祝福玩得好", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 36, "en": "Which film? — We shall see.", "zh": "看哪部电影？— 到时候就知道了。", "note": "保持神秘 We shall see", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 37, "en": "You and Hector are going to the cinema? I don't believe it!", "zh": "你和赫克托要去看电影？我才不信呢！", "note": "吃惊难以置信", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 38, "en": "All the films are rubbish at the moment anyway.", "zh": "反正现在的电影全都是大烂片。", "note": "酸溜溜吐槽 rubbish", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 39, "en": "So Nick and Hector don't know that you are twins?", "zh": "所以尼克和赫克托还不知道你们是双胞胎？", "note": "确认事实", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 40, "en": "You know, we could have some fun with this!", "zh": "你知道吗，咱们完全可以用这个好好捉弄他们一番！", "note": "恶作剧提议 have fun", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 41, "en": "Maybe a magic trick?", "zh": "比如变个魔术怎么样？", "note": "灵感提议", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 42, "en": "You are just in time to see my new magic trick.", "zh": "你们来得正是时候，看我的新魔术表演。", "note": "地道句型 just in time", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 43, "en": "Take a seat. — Wow, I can't wait!", "zh": "请坐。— 哇，我都等不及了！", "note": "观赏开场", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 44, "en": "Today, I will make my lovely assistant disappear.", "zh": "今天，我将让我可爱的助手神奇消失。", "note": "魔术经典台词", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 45, "en": "In you go.", "zh": "进去吧。", "note": "日常口语指令", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 46, "en": "Disappear from this box and appear in this box!", "zh": "从这个箱子里消失，并在那个箱子里现身！", "note": "魔术口诀", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 47, "en": "Oh, this I must see!", "zh": "噢，这我可必须得好好看看！", "note": "倒装口语强调", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 48, "en": "Now, a tap with the magic wand.", "zh": "现在，用魔杖轻轻敲一下。", "note": "魔术道具 magic wand", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 49, "en": "Place your bets, please.", "zh": "各位观众，请下注吧！", "note": "竞猜邀请", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 50, "en": "Which box do you think Bridget is in?", "zh": "你们觉得布里吉特在哪个箱子里？", "note": "插入疑问句型", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 51, "en": "The box on the left, or the box on the right?", "zh": "左边的箱子，还是右边的箱子？", "note": "方位二选一", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 52, "en": "A drum roll, please!", "zh": "请现场乐队擂鼓伴奏！", "note": "揭晓前烘托气氛 drum roll", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 53, "en": "Applause, please, for Bridget and Chrissy!", "zh": "请大家为布里吉特和克丽茜热烈鼓掌！", "note": "热烈鼓掌 applause", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 54, "en": "I'll miss you.", "zh": "我会想你的。", "note": "离别深情表达", "b64": "", "src": "extra"}, {"l": 107, "lt": "Extra E07 双胞胎", "i": 55, "en": "It can't be!", "zh": "这绝不可能！/ 不会吧！", "note": "极度震惊感叹", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 1, "en": "We need to talk about your rent in private.", "zh": "我们需要私下谈谈你的房租问题。", "note": "私下沟通 in private", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 2, "en": "Measure the distance between the shelves.", "zh": "量一下隔板架之间的距离。", "note": "测量指示 measure", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 3, "en": "Annie, hold this, please.", "zh": "安妮，请帮我拿着这个。", "note": "请人帮忙 hold this", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 4, "en": "I think that's correct.", "zh": "我想这样应该就对了。", "note": "确认正确", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 5, "en": "One of the richest families in Argentina.", "zh": "阿根廷最富有的家族之一。", "note": "家族背景介绍", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 6, "en": "So why the secret?", "zh": "那为什么还要瞒着大家呢？", "note": "追问保密动机", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 7, "en": "Because I wanted you to like me, not my money.", "zh": "因为我想让你喜欢我这个人，而不是喜欢我的钱。", "note": "真诚深情表白", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 8, "en": "Who else knows? — But not Annie.", "zh": "还有谁知道这件事？— 但安妮还不知道。", "note": "核实知情范围", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 9, "en": "Don't tell Annie yet.", "zh": "先别告诉安妮。", "note": "暂时保密", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 10, "en": "I am in love with Annie.", "zh": "我深深爱上了安妮。", "note": "深情表白 in love with", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 11, "en": "Where are you going looking like John Travolta?", "zh": "你打扮得像约翰·特拉沃尔塔一样是要去哪儿？", "note": "调侃穿搭", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 12, "en": "He has a date with me, haven't you?", "zh": "他今晚跟我有约会，对吧？", "note": "反义疑问句 haven't you", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 13, "en": "Another date? Three times this week!", "zh": "又约会？这星期都第三次了！", "note": "感叹约会频繁", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 14, "en": "We've been to dinner, to the theatre, to the cinema.", "zh": "我们去吃了晚餐，看了戏剧，去了电影院。", "note": "列举约会项目", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 15, "en": "And last night: Salsa dancing!", "zh": "昨晚还去跳了萨尔萨舞！", "note": "舞蹈词汇 salsa", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 16, "en": "Can you salsa? — Two left feet.", "zh": "你会跳萨尔萨吗？— 我笨手笨脚，完全不会跳。", "note": "英语习语笨拙 two left feet", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 17, "en": "Tonight it's karaoke, and I am the karaoke queen!", "zh": "今晚去唱K，我可是卡拉OK女王！", "note": "高调自夸", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 18, "en": "I bet she sings like a toad.", "zh": "我敢打赌她唱歌难听得像蛤蟆叫。", "note": "刻薄幽默吐槽 toad", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 19, "en": "Let me repeat the rules: no parties, and no visitors!", "zh": "我重申一遍规矩：不准开派对，不准带访客！", "note": "重申规则 repeat the rules", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 20, "en": "Especially boys from next door!", "zh": "尤其是隔壁住的男孩子！", "note": "重点强调 especially", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 21, "en": "Get the message? See you later.", "zh": "听明白了吗？回见。", "note": "警告语气 Get the message", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 22, "en": "How dare she!", "zh": "她怎么敢这么嚣张！/ 她算老几！", "note": "强烈愤慨 How dare she", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 23, "en": "How is Eunice? — She is very nice, but she's just not my type.", "zh": "尤妮斯怎么样？— 她人挺好，但根本不是我喜欢的类型。", "note": "经典择偶口语 not my type", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 24, "en": "And her energy! I'm exhausted.", "zh": "还有她的精力实在太旺盛了，我都快累趴了！", "note": "身心俱疲 exhausted", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 25, "en": "Get rid of her! Say something!", "zh": "快把她打发走！随便说点什么！", "note": "摆脱某人 get rid of", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 26, "en": "Tell her I'm not well.", "zh": "跟她说我身体不舒服。", "note": "找借口推脱", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 27, "en": "Nick, are you in there?", "zh": "尼克，你在里面吗？", "note": "敲门询问", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 28, "en": "Nick cannot dance. He stood on a hedgehog without shoes.", "zh": "尼克没法跳舞，他光脚踩在刺猬上了。", "note": "搞笑荒诞借口 hedgehog", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 29, "en": "Very painful! Very messy!", "zh": "痛得要命！血肉模糊！", "note": "夸大其词", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 30, "en": "Oh, that's a pity. Never mind.", "zh": "哎呀，那真可惜。没关系。", "note": "表示遗憾与算了", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 31, "en": "Hector is still building the shelves.", "zh": "赫克托还在帮忙装书架呢。", "note": "现在进行时", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 32, "en": "I don't know why he's so keen to help. Still, I like it.", "zh": "我不知道他为什么这么热心帮忙，不过我挺喜欢的。", "note": "短语 keen to help", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 33, "en": "Poor Nick. He looks exhausted.", "zh": "可怜的尼克，他看起来筋疲力尽。", "note": "同情朋友", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 34, "en": "I don't think Bridget likes her.", "zh": "我觉得布里吉特并不喜欢她。", "note": "委婉看法", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 35, "en": "Tighten the screws. Annie, you are a genius!", "zh": "把螺丝拧紧。安妮，你真是个天才！", "note": "装配工具词汇 tighten screws", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 36, "en": "Are you okay? — I am exhausted.", "zh": "你还好吧？— 我彻底累瘫了。", "note": "精疲力竭问答", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 37, "en": "She dances like a rhinoceros!", "zh": "她跳起舞来就像一头大犀牛！", "note": "绝妙讽刺明喻 rhinoceros", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 38, "en": "You finished the shelves!", "zh": "你把架子全组装好了！", "note": "惊喜夸赞", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 39, "en": "Oh, just a bit more measuring. I will help you.", "zh": "噢，还得再稍加测量一下，我来帮你。", "note": "主动搭手", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 40, "en": "Bridget, save me! It's Eunice!", "zh": "布里吉特，救救我！是尤妮斯来了！", "note": "求救呼喊 save me", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 41, "en": "Shall I get rid of her, Nick? — Oh, yes, please!", "zh": "需要我帮你把她打发走吗，尼克？— 噢，太需要了，求你了！", "note": "挺身而出", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 42, "en": "I'll think of something.", "zh": "我会想出办法来的。", "note": "自信承诺想办法", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 43, "en": "There you are, Nick!", "zh": "原来你在这儿啊，尼克！", "note": "抓到目标口语", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 44, "en": "Wait until I tell my cousin!", "zh": "等我把这事告诉我表姐房东！", "note": "威胁告状 wait until", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 45, "en": "I've got a fax for you. It's from your father.", "zh": "我有一份传真要给你，是你父亲发来的。", "note": "办公通信 fax", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 46, "en": "Coming to London to meet the Prime Minister.", "zh": "正赶来伦敦与首相会晤。", "note": "高大上政要词汇 Prime Minister", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 47, "en": "My private jet arrives at midday.", "zh": "我的私人专机将在中午抵达。", "note": "奢华词汇 private jet", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 48, "en": "Actually, Hector, I think you're more my type!", "zh": "其实嘛，赫克托，我觉得你才是我喜欢的类型！", "note": "见风使舵经典台词", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 49, "en": "I don't think so, Eunice!", "zh": "我可不这么认为，尤妮斯！", "note": "当场打脸回绝", "b64": "", "src": "extra"}, {"l": 108, "lt": "Extra E08 房东太太的表妹", "i": 50, "en": "Annie, I will buy you a million shelves!", "zh": "安妮，我愿意为你买下一百万个书架！", "note": "豪气浪漫表白", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 1, "en": "Did you get my email?", "zh": "你收到我的电子邮件了吗？", "note": "工作邮件核实", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 2, "en": "Will he do the interview?", "zh": "他愿意接受采访吗？", "note": "媒体采访 interview", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 3, "en": "Listen, I must go out for one hour.", "zh": "听着，我得出去一个小时。", "note": "交代外出时间", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 4, "en": "Don't worry. Just remember everything I've told you.", "zh": "别担心，牢记我教你的每件事就行。", "note": "上场前嘱托", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 5, "en": "Here's the script, there's the camera.", "zh": "这是剧本，那是摄像机镜头。", "note": "演播现场指引", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 6, "en": "This is Hector Romero for Channel 9.", "zh": "我是第九频道的记者赫克托·罗梅罗。", "note": "经典电视出镜记者台词", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 7, "en": "So, have I got the job? — What do you think?", "zh": "那……我拿到工作了吗？— 你觉得呢？", "note": "试镜后忐忑询问", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 8, "en": "The new editor will be here soon.", "zh": "新主编/责编马上就要到了。", "note": "职场高频 editor", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 9, "en": "I am too angry to speak!", "zh": "我气得话都说不出来了！", "note": "too... to 句型极度愤怒", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 10, "en": "Shut up, Nick! How dare you?", "zh": "闭嘴，尼克！你怎么敢这样？", "note": "愤怒制止", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 11, "en": "He was ridiculous!", "zh": "他表现得简直太荒唐滑稽了！", "note": "吐槽表现 ridiculous", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 12, "en": "Hi sexy, this is Hector Romero.", "zh": "嗨性感尤物，我是赫克托·罗梅罗。", "note": "搞笑浮夸搭讪台词", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 13, "en": "I wanted to impress her.", "zh": "我本想给她留下个好印象的。", "note": "表达意图 impress her", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 14, "en": "Of course he won't get the job!", "zh": "他当然不可能拿到这份工作！", "note": "断言绝无可能", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 15, "en": "You made me look like a fool!", "zh": "你让我看起来像个十足的傻瓜！", "note": "责怪对方让其出丑", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 16, "en": "This could be perfect for you.", "zh": "这个机会对你来说可能太完美了。", "note": "推荐绝佳机会", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 17, "en": "Do you love performing? Do you love travelling?", "zh": "你热爱表演吗？你喜欢到处旅行吗？", "note": "招聘煽动性排比", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 18, "en": "Do people adore you? — Naturally.", "zh": "大家都崇拜仰慕你吗？— 那是自然。", "note": "迷之自信 adore / naturally", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 19, "en": "Call this number for a Shakespearean experience.", "zh": "拨打此热线，体验莎士比亚戏剧的魅力。", "note": "广告宣传词", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 20, "en": "Hamlet! My dream! I'll call now.", "zh": "哈姆雷特！我的终极梦想！我现在就打。", "note": "兴奋接招", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 21, "en": "To be, or not to be.", "zh": "生存还是毁灭，这是一个问题。", "note": "莎翁经典名句", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 22, "en": "What are you doing here?", "zh": "你在这里干什么？", "note": "意外相遇质问", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 23, "en": "Long time no see, Bridget.", "zh": "好久不见啊，布里吉特。", "note": "老友重逢打招呼", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 24, "en": "I have a new hairstyle. — So have I.", "zh": "我换了新发型。— 我也是。", "note": "经典口语倒装 So have I", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 25, "en": "Mine looks good.", "zh": "但我剪出来很好看。", "note": "嘴碎反击", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 26, "en": "Bridget, I am your new editor. Surprised?", "zh": "布里吉特，我是你的新主编。意外吗？", "note": "职场降维打击", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 27, "en": "I am your editor and I am always right.", "zh": "我是你的主编，我永远都是对的。", "note": "专制老板名言", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 28, "en": "You are the researcher. You are always wrong.", "zh": "你是调查资料员，你永远都是错的。", "note": "职场上下级规矩", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 29, "en": "We need a new reporter.", "zh": "我们需要一名新的出镜记者。", "note": "媒体招人", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 30, "en": "I know the most perfect person.", "zh": "我正好知道一个绝佳人选！", "note": "主动推荐", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 31, "en": "He's Latin American, speaks English, and he's very sexy.", "zh": "他是拉美帅哥，会讲英语，而且性感极了。", "note": "人物推介", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 32, "en": "Watch this. I know you'll love him.", "zh": "看看这个录像，我知道你肯定会爱上他。", "note": "安利推荐", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 33, "en": "You look beautiful today.", "zh": "你今天看起来真迷人。", "note": "真诚称赞", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 34, "en": "There's been a diamond robbery in London.", "zh": "伦敦发生了一起重大钻石抢劫案。", "note": "新闻案件词汇 diamond robbery", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 35, "en": "I would love to put diamonds on those pretty ears.", "zh": "我真想给你那漂亮的耳朵戴上璀璨钻石。", "note": "电视撩妹语录", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 36, "en": "You can sleep safely in your bed tonight.", "zh": "今晚你可以高枕无忧安然入睡了。", "note": "记者安抚市民套话", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 37, "en": "I'll be back.", "zh": "我还会再回来的。", "note": "终结者经典台词", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 38, "en": "Hector's audition was a disaster.", "zh": "赫克托的试镜简直是一场大灾难。", "note": "评价糟糕 disaster", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 39, "en": "Guess who is my new boss?", "zh": "你猜谁成了我的顶头上司？", "note": "震惊吐槽", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 40, "en": "The good news is, she loved Hector!", "zh": "但好消息是，她彻底看上赫克托了！", "note": "峰回路转", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 41, "en": "Don't worry about Bridget.", "zh": "别担心布里吉特啦。", "note": "日常宽慰", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 42, "en": "Guess what? I've got the job!", "zh": "你猜怎么着？我拿到工作了！", "note": "狂喜分享", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 43, "en": "Congratulations, man!", "zh": "恭喜你啊，哥们儿！", "note": "祝贺朋友", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 44, "en": "I've got the costume already.", "zh": "我已经把演出服装拿到手了。", "note": "戏服 costume", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 45, "en": "I came to say congratulations.", "zh": "我是专程过来向你道喜祝贺的。", "note": "礼貌道喜", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 46, "en": "See you at eight o'clock sharp tomorrow morning.", "zh": "明早八点整准时见！", "note": "时间准时 sharp", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 47, "en": "There's no need to thank me, Hector.", "zh": "根本不用谢我，赫克托。", "note": "客气回应 no need to thank", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 48, "en": "Whatever happens, we will always be together.", "zh": "不论发生什么，我们都会永远在一起。", "note": "深情誓言 Whatever happens", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 49, "en": "I shall never forget you. You're the light of my life.", "zh": "我永远都不会忘记你，你是我生命中的光芒。", "note": "浪漫至极表白 light of my life", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 50, "en": "To eat, or not to eat? That is the question.", "zh": "吃，还是不吃？这是一个问题。", "note": "汉堡广告恶搞名句", "b64": "", "src": "extra"}, {"l": 109, "lt": "Extra E09 男孩们的工作", "i": 51, "en": "Hamlet Burgers: eat them without question!", "zh": "哈姆雷特汉堡：不假思索，大快朵颐！", "note": "汉堡广告词", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 1, "en": "How important is this protest?", "zh": "这次抗议示威有多重要？", "note": "抗议活动重要性", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 2, "en": "This factory experiments on animals.", "zh": "这家工厂用动物做残酷的活体实验。", "note": "动物实验 experiment on", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 3, "en": "And why is that bad? — Because the poor animals are suffering!", "zh": "这有什么不好的？— 因为可怜的动物们在受苦受难！", "note": "控诉苦难 suffering", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 4, "en": "Oh, that's dreadful! The poor things.", "zh": "噢，那太可怕残忍了！可怜的小生灵们。", "note": "同情表达 dreadful / poor things", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 5, "en": "Do you think this march will help the animals?", "zh": "你觉得这次游行能帮到动物们吗？", "note": "游行词汇 march", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 6, "en": "They use the poor animals to test hair dye and mascara.", "zh": "他们用可怜的动物测试染发剂和睫毛膏！", "note": "化妆品词汇 hair dye / mascara", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 7, "en": "The guinea pigs are safe with me.", "zh": "这些豚鼠/荷兰猪在我这儿非常安全。", "note": "动物词汇 guinea pigs", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 8, "en": "Have you got the guinea pigs?", "zh": "是你把那些豚鼠藏起来了吗？", "note": "质问藏匿", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 9, "en": "Why are you doing this? You know I love animals!", "zh": "你为什么要这么做？你明知道我最爱动物！", "note": "委屈质问", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 10, "en": "I'm sorry, Annie. It's my job.", "zh": "对不起，安妮。这是我的本职工作。", "note": "职场身不由己无奈", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 11, "en": "Well, then keep your job!", "zh": "行啊，那你留着你的破工作过吧！", "note": "气话绝交 keep your job", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 12, "en": "Annie, please! I can't explain!", "zh": "安妮，求你了！我没法解释！", "note": "百口莫辩", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 13, "en": "His questions were so unfair.", "zh": "他问的问题实在太不公道、太刻薄了。", "note": "评价不公 unfair", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 14, "en": "Aren't you going to ask me about my lunch?", "zh": "你们难道不打算问问我午饭跟谁吃的吗？", "note": "傲娇主动炫耀", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 15, "en": "My lunch with Leonardo, of course!", "zh": "当然是跟我跟莱昂纳多的午餐啦！", "note": "大牌炫耀", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 16, "en": "How was your lunch with Leonardo DiCaprio?", "zh": "那你和小李子莱昂纳多的午餐怎么样？", "note": "捧场顺水推舟", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 17, "en": "He loved me, he loved my dress, he loved my name!", "zh": "他超喜欢我，超喜欢我的裙子，超喜欢我的名字！", "note": "自恋三连排比", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 18, "en": "Close your eyes. Go on, close your eyes.", "zh": "闭上眼睛。快点，把眼睛闭上。", "note": "展示惊喜指令", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 19, "en": "What do you think? — Very nice.", "zh": "你觉得怎么样？— 非常漂亮。", "note": "征求穿搭意见", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 20, "en": "It was very expensive, but it's worth it.", "zh": "这件贵得要命，但物超所值！", "note": "高频消费心理 worth it", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 21, "en": "Tonight, I'm going to a premiere! I can't wait!", "zh": "今晚我要去参加电影首映礼！我都等不及了！", "note": "首映礼词汇 premiere", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 22, "en": "Tonight, this little lady is going to shine!", "zh": "今晚，这位漂亮小姐将大放异彩！", "note": "闪耀全场 to shine", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 23, "en": "Annie, please talk to me.", "zh": "安妮，求求你跟我说句话吧。", "note": "恳求沟通", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 24, "en": "You were asking awful questions. — It wasn't me, it was Eunice!", "zh": "你问的问题太恶劣了。— 那不是我的主意，是尤妮斯逼我的！", "note": "甩锅澄清真相", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 25, "en": "I must take them to the animal sanctuary.", "zh": "我必须把它们送到动物收容保护所去。", "note": "动保所 animal sanctuary", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 26, "en": "They're not here! — What do you mean, they're not here?", "zh": "它们不在箱子里！— 你什么意思，不在箱子里？", "note": "惊恐发现失踪", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 27, "en": "She is so pleased with the interview.", "zh": "她对这次现场采访非常满意！", "note": "表达满意 pleased with", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 28, "en": "She wants Channel 9 to fight against animal cruelty.", "zh": "她希望第九频道带头反对虐待动物！", "note": "反对虐待 animal cruelty", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 29, "en": "Channel 9's new motto is: Animals are human too!", "zh": "第九频道的新口号是：动物也是有血有肉的生灵！", "note": "官方口号 motto", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 30, "en": "Don't worry about Mr. Gariar.", "zh": "不用担心那个加里埃老板了。", "note": "摆平麻烦", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 31, "en": "There's just one guinea pig still missing.", "zh": "就只剩一只豚鼠还没找到了。", "note": "依旧失踪 still missing", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 32, "en": "Bridget, your taxi is here!", "zh": "布里吉特，你叫的出租车到楼下了！", "note": "出门提醒", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 33, "en": "Everyone, I'm just off to my premiere.", "zh": "各位，我马上就要动身去首映礼了。", "note": "告别出门 off to", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 34, "en": "Did I mention it? Proper acting!", "zh": "我提过了吗？这才是真正专业的表演！", "note": "傲慢调侃 proper acting", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 35, "en": "Perhaps you could learn something, Nick.", "zh": "说不定你能学到点真本事呢，尼克。", "note": "日常损友戏谑", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 36, "en": "Sorry, no spare ticket!", "zh": "抱歉哦，没有多余的赠票给你们！", "note": "多余的票 spare ticket", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 37, "en": "Still, I'll tell you all about it later.", "zh": "不过嘛，回头我会把精彩细节都讲给你们听的。", "note": "炫耀收尾", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 38, "en": "Next time in Extra, the friends go on holiday to Spain!", "zh": "下集预告，小伙伴们要一起去西班牙度假啦！", "note": "度假预告 on holiday", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 39, "en": "Bridget finds her prince, and Nick finds his princess.", "zh": "布里吉特找到了她的白马王子，尼克也找到了他的公主。", "note": "童话式预告", "b64": "", "src": "extra"}, {"l": 110, "lt": "Extra E10 安妮的抗议", "i": 40, "en": "Extra, don't miss it!", "zh": "《Extra》，精彩千万别错过！", "note": "剧集招牌收尾", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 1, "en": "You must do a final check.", "zh": "你必须做最后的检查确认。", "note": "出行前检查 final check", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 2, "en": "What's in there? Six t-shirts, three pairs of jeans.", "zh": "里面装了什么？六件T恤，三条牛仔裤。", "note": "行李物品清点", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 3, "en": "Four pairs of trousers, ten bikinis, four sarongs.", "zh": "四条长裤，十套比基尼，四条沙滩裹裙。", "note": "度假服饰词汇", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 4, "en": "Two nightdresses, three pairs of trainers.", "zh": "两件睡裙，三双运动跑鞋。", "note": "实用鞋履 trainers", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 5, "en": "Two pairs of evening shoes, three toothbrushes.", "zh": "两双晚宴高跟鞋，三把牙刷。", "note": "生活用品 toothbrushes", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 6, "en": "Two toilet bags, five belts, two jackets, and a ballgown!", "zh": "两个洗漱包，五条腰带，两件夹克，还有一件晚礼服！", "note": "浮夸行李 ballgown", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 7, "en": "But we're only going for three days!", "zh": "可我们只去三天而已啊！", "note": "极度震惊吐槽", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 8, "en": "You never can be sure what event we'll be asked to go to.", "zh": "你永远拿不准我们会受邀出席什么高档场合。", "note": "名媛派头预判", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 9, "en": "When Bridget arrives in Spain, we'll be invited everywhere.", "zh": "当布里吉特抵达西班牙，各地都会争相邀请我们！", "note": "迷之自信自吹", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 10, "en": "They just won't be able to resist.", "zh": "他们根本抵挡不住我的魅力。", "note": "习语 won't be able to resist", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 11, "en": "You are taking all that? — Yeah, why?", "zh": "你要把所有这些全带上？— 对啊，怎么了？", "note": "疑问对白", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 12, "en": "All you need to travel is your passport, your tickets, and your money.", "zh": "旅行真正需要的就三样东西：护照、车票和钱。", "note": "出行极简至理名言", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 13, "en": "That will be the taxi. Let's go!", "zh": "肯定是出租车到了，咱们出发吧！", "note": "推测情态动词 That will be", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 14, "en": "Give me a hand with my luggage.", "zh": "快来帮我提一下行李。", "note": "请求搭手 give me a hand", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 15, "en": "Typical Spanish hospitality.", "zh": "典型的西班牙式热情好客。", "note": "文化风情词汇 hospitality", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 16, "en": "And this is a typical happy Spanish waitress.", "zh": "而这位就是典型的快乐西班牙女侍者。", "note": "反讽吐槽 waitress", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 17, "en": "We would like a drink, please.", "zh": "我们想喝点东西，麻烦了。", "note": "礼貌点饮品", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 18, "en": "Leave it to me. I must translate for you.", "zh": "交给我吧，我来替你们翻译。", "note": "自告奋勇当翻译", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 19, "en": "We want to drink something typically Spanish.", "zh": "我们想在这家极具西班牙特色的小酒吧喝点特色饮品。", "note": "地道体验", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 20, "en": "She doesn't look very happy. No, she looks a mess.", "zh": "她看起来可不太高兴。岂止，看起来糟透了。", "note": "外貌气色评价 a mess", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 21, "en": "Perhaps her boyfriend has left her.", "zh": "说不定是她男朋友把她给甩了。", "note": "八卦推测", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 22, "en": "He did like my hair! And at least mine is natural!", "zh": "他明明很喜欢我的头发！而且至少我的头发是天生的纯天然！", "note": "气愤反击 natural", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 23, "en": "She understood! She's English!", "zh": "她听懂了！她是英国人！", "note": "被当场抓包尴尬", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 24, "en": "How did you guess?", "zh": "你是怎么猜出来的？", "note": "日常反问", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 25, "en": "Is this a traditional Spanish bar? — It's an English tea room!", "zh": "这是一家传统西班牙酒吧吗？— 这是英式茶餐厅！", "note": "经典反转搞笑 tea room", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 26, "en": "An English tea room in Barcelona?!", "zh": "在巴塞罗那开英式茶室？！", "note": "不可思议感叹", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 27, "en": "Aren't you clever?", "zh": "你可真聪明啊！", "note": "反讽讽刺", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 28, "en": "Can we have a drink?", "zh": "我们能喝点什么吗？", "note": "基础点单", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 29, "en": "What about this table here? — It's reserved.", "zh": "靠这里的这桌怎么样？— 已经有人预订了。", "note": "餐厅预定 reserved", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 30, "en": "If you reserve the table, you can come in.", "zh": "只要你们预订了桌位，就可以进来了。", "note": "条件句口语", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 31, "en": "Can we please reserve a table? — Certainly.", "zh": "那我们现在预订一张桌子行吗？— 当然可以。", "note": "现学现用 Certainly", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 32, "en": "What would you like to drink? — Cola, please.", "zh": "几位想喝点什么？— 请来杯可乐。", "note": "点餐标准问答", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 33, "en": "In Spain, do as the English do.", "zh": "在西班牙，入乡随俗学英国人。", "note": "化用俗语入乡随俗", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 34, "en": "I will have a nice cup of tea, please.", "zh": "请给我来一杯香浓的热茶。", "note": "英式点茶", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 35, "en": "Which tea? What have you got?", "zh": "哪种茶？你们这儿有什么品种？", "note": "询问茶种种类", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 36, "en": "English breakfast, Earl Grey, Peppermint, Jasmine, and Green.", "zh": "英式红茶、伯爵红茶、薄荷茶、茉莉花茶和绿茶。", "note": "西式茶文化词汇", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 37, "en": "I'll have a cola, please.", "zh": "我还是喝可乐吧，谢谢。", "note": "放弃纠结", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 38, "en": "Anything to eat? — Yes, please. What have you got?", "zh": "需要吃点什么吗？— 好的，你们有什么吃的？", "note": "餐厅点餐", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 39, "en": "Fish and chips, pie and chips, chicken and chips.", "zh": "炸鱼薯条，馅饼薯条，炸鸡薯条。", "note": "英式万物配薯条 chips", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 40, "en": "So we can have anything with chips!", "zh": "所以我们不管点什么，配菜全都是薯条！", "note": "灵魂总结吐槽", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 41, "en": "Or I have cake. I think she means gâteau.", "zh": "或者我这儿还有蛋糕。我想她的意思是法式蛋糕。", "note": "甜点词汇 gâteau", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 42, "en": "I don't believe it! Over there!", "zh": "我简直不敢相信我的眼睛！看那边！", "note": "偶遇明星震惊", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 43, "en": "He's gorgeous! I must go and talk to him.", "zh": "他长得太帅了！我必须过去跟他说说话。", "note": "主动搭讪", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 44, "en": "Latin men are different from English men.", "zh": "拉美男人和英国男人可不一样。", "note": "文化对比", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 45, "en": "They are sensitive, gentle, romantic and sophisticated, like me.", "zh": "他们体贴、温柔、浪漫而且成熟有品位，就像我一样。", "note": "迷之自夸 sophisticated", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 46, "en": "Try one of your chat-up lines on her.", "zh": "对她试试你那些搭讪泡妞金句呗。", "note": "地道俚语 chat-up lines", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 47, "en": "She's not my type.", "zh": "她根本不是我喜欢的类型。", "note": "经典托词", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 48, "en": "Your teeth are like stars: they come out at night!", "zh": "你的牙齿就像天上的星星：一到晚上才出来（假牙）！", "note": "翻车搭讪土味笑话", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 49, "en": "I've got a date with him! Tonight we're going clubbing!", "zh": "我和他约好了！今晚我们要去酒吧蹦迪！", "note": "约会成功炫耀", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 50, "en": "We must be your chaperones.", "zh": "我们必须全程当你的护花使者/监护人。", "note": "文化词汇 chaperone", "b64": "", "src": "extra"}, {"l": 111, "lt": "Extra E11 假日时光", "i": 51, "en": "I'll show you how it's done!", "zh": "我来给你们展示展示专业做法！", "note": "高频自信口语 how it's done", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 1, "en": "It's a disaster! It's a catastrophe!", "zh": "这是一场灾难！简直是弥天大祸！", "note": "夸张崩溃感叹", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 2, "en": "What is a catastrophe? — Bridget's hair!", "zh": "什么弥天大祸？— 布里吉特的头发！", "note": "揭露真相发型崩塌", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 3, "en": "This is an emergency. I need a hair appointment.", "zh": "这是紧急军情，我必须立刻预约美发！", "note": "紧急求助 appointment", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 4, "en": "I need a style that a Spanish football fan will adore.", "zh": "我需要一款能把西班牙球迷迷得神魂颠倒的发型。", "note": "明确审美诉求", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 5, "en": "I'll see you at five o'clock.", "zh": "那我们五点钟见。", "note": "约定时间", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 6, "en": "Come on, England! — Come on, Argentina!", "zh": "加油，英格兰！— 加油，阿根廷！", "note": "球场助威 Come on", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 7, "en": "They played very well against England, but not well enough.", "zh": "他们对阵英格兰踢得非常出色，但还不够好。", "note": "球赛客观评价", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 8, "en": "We must not look too happy.", "zh": "我们千万不能表现得太幸灾乐祸/太开心。", "note": "照顾朋友情绪", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 9, "en": "We promised Nick not to tell him the score.", "zh": "我们答应过尼克绝不剧透比分的。", "note": "遵守承诺 not to tell", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 10, "en": "You must not look too sad. Try to smile!", "zh": "你不能看起来太难过，试着笑一笑！", "note": "安抚失利球迷", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 11, "en": "Where's the tape? — Hector's got it.", "zh": "录像带在哪儿？— 在赫克托那儿。", "note": "询问物品", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 12, "en": "Is this the football match?", "zh": "这就是那场足球比赛的录像吗？", "note": "核对录像", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 13, "en": "Argentina beat England, didn't they?", "zh": "阿根廷打败了英格兰，对不对？", "note": "反义疑问句 beat", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 14, "en": "I promised you I wouldn't say anything.", "zh": "我答应过你什么都不透露的。", "note": "保密誓言", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 15, "en": "You're so happy. — No, I'm not!", "zh": "你开心得很嘛。— 哪有，我才没有！", "note": "嘴硬掩饰", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 16, "en": "You can watch the match on video.", "zh": "你可以看录像重播比赛。", "note": "看重播", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 17, "en": "I can't bear it! How could you?", "zh": "我受不了了！你怎么能这样？", "note": "难以忍受 can't bear it", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 18, "en": "How could Argentina beat England?", "zh": "阿根廷怎么可能踢赢英格兰？！", "note": "痛心疾首", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 19, "en": "Just watch the tape.", "zh": "你自己看录像就知道了。", "note": "让事实说话", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 20, "en": "I need to learn English for Bridget.", "zh": "为了布里吉特，我需要好好学学英语。", "note": "学习动机", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 21, "en": "Repeat after me.", "zh": "跟我念 / 跟着我重复一遍。", "note": "口语教学经典指令", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 22, "en": "Bridget, you are so beautiful.", "zh": "布里吉特，你真美。", "note": "经典赞叹", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 23, "en": "Bridget, I love your hair and your smile.", "zh": "布里吉特，我好喜欢你的秀发和你的笑容。", "note": "暖心夸赞组合", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 24, "en": "Thank you very much. — No problem. See you later.", "zh": "非常感谢你。— 不客气，回头见。", "note": "客气道别", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 25, "en": "England beat Argentina, but only a little bit.", "zh": "英格兰击败了阿根廷，但其实就险胜一点点。", "note": "委婉安慰", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 26, "en": "Bridget is having a bad hair day today.", "zh": "布里吉特今天发型彻底翻车了。", "note": "英语经典俗语 bad hair day", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 27, "en": "She is worried because Miguel is arriving this evening.", "zh": "她急坏了，因为米格尔今晚就要到了。", "note": "道出焦虑原因", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 28, "en": "I need a hair appointment!", "zh": "我急需预约做头发！", "note": "美发急救", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 29, "en": "I don't understand.", "zh": "我彻底想不通了。", "note": "表达困惑", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 30, "en": "Annie, are you all right? Are you cross about something?", "zh": "安妮，你没事吧？你是在为什么事生闷气吗？", "note": "英式表达生气 cross", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 31, "en": "Come and sit down.", "zh": "快过来坐下吧。", "note": "体贴安抚", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 32, "en": "Annie, have I done something wrong?", "zh": "安妮，是我做错什么事惹你生气了吗？", "note": "诚恳反思", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 33, "en": "Well, if you don't tell me, how am I to know?", "zh": "好吧，要是你什么都不说，我怎么会知道呢？", "note": "无奈沟通困境", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 34, "en": "Oh, you know, Hector, you know!", "zh": "噢，你自己心里清楚，赫克托，你心知肚明！", "note": "女生经典赌气台词", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 35, "en": "Bridget, you have a bag on your head!", "zh": "布里吉特，你头上套了个大纸袋！", "note": "搞笑视觉吐槽", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 36, "en": "Come on, let's take it off.", "zh": "好啦，快把它拿下来吧。", "note": "劝说揭下", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 37, "en": "Trust me, Bridget. He will love your hair.", "zh": "相信我，布里吉特，他肯定会喜欢你的发型的。", "note": "安抚自信", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 38, "en": "Spain versus England in the World Cup Final!", "zh": "西班牙对决英格兰，世界杯总决赛！", "note": "赛事巅峰 versus", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 39, "en": "Poor old England!", "zh": "可怜的老英格兰队要输咯！", "note": "对手挑衅调侃", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 40, "en": "On the contrary, my Spanish friend: prepare to die!", "zh": "恰恰相反，我的西班牙朋友：洗干净脖子等死吧！", "note": "地道霸气反击 On the contrary", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 41, "en": "Can you pass the crisps?", "zh": "能麻烦把薯片递过来一下吗？", "note": "看球零食词汇 crisps", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 42, "en": "Why hasn't she spoken to me for two days?", "zh": "她为什么整整两天都不理我、不跟我说话了？", "note": "困惑求助冷战", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 43, "en": "Come on, England!", "zh": "英格兰加油！冲啊！", "note": "呐喊助威", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 44, "en": "Can I ask you something?", "zh": "我能问你一件事情吗？", "note": "郑重发问", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 45, "en": "Have you ever thought about getting married?", "zh": "你曾经考虑过结婚这件事吗？", "note": "求婚试探", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 46, "en": "To someone like me.", "zh": "比如，跟我这样的人结婚。", "note": "深情试探", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 47, "en": "It's my English again!", "zh": "又是我那糟糕的英语惹的祸！", "note": "语言误会自嘲", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 48, "en": "I was teaching him English on the phone!", "zh": "我刚才只是在电话里教他说英语而已啊！", "note": "破除误会解释", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 49, "en": "Oh, I thought you were talking to Bridget!", "zh": "噢天哪，我还以为你当时是在对布里吉特表白呢！", "note": "恍然大悟解开误会", "b64": "", "src": "extra"}, {"l": 112, "lt": "Extra E12 狂热足球", "i": 50, "en": "There is only one person for me, Annie.", "zh": "对我来说，我的心里永远只有一个人，安妮。", "note": "经典纯爱深情表白", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 1, "en": "Hector and Annie want to get married.", "zh": "赫克托和安妮想要步入婚姻的殿堂了。", "note": "交代主线 want to", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 2, "en": "Bridget also wants to get married, but to whom?", "zh": "布里吉特也渴望结婚，但问题是跟谁结呢？", "note": "灵魂发问 but to whom", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 3, "en": "And Nick just wants to get away.", "zh": "至于尼克嘛，他只想赶紧溜之大吉。", "note": "诙谐调侃 get away", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 4, "en": "Hector, you have mail. And they're all from your mother.", "zh": "赫克托，你有新邮件，而且全是你妈妈发来的。", "note": "查收邮件 have mail", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 5, "en": "How many bridesmaids is Annie having, ten or twelve?", "zh": "安妮打算请多少位伴娘，十个还是十二个？", "note": "婚礼筹备 bridesmaids", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 6, "en": "Have you booked Westminster Abbey yet?", "zh": "你们预订好威斯敏斯特大教堂了吗？", "note": "夸张排场 booked yet", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 7, "en": "I'm coming to London soon to help you.", "zh": "我马上就要来伦敦帮你们操办了。", "note": "热情插手 coming soon", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 8, "en": "Hector, your mother is very kind, but she must not interfere.", "zh": "赫克托，你妈妈人很好，但她绝不能横加干涉。", "note": "设立边界 must not interfere", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 9, "en": "She must not interfere anymore. — It's okay. I won't let her come here.", "zh": "她绝对不能再干预了。— 放心，我不会让她过来的。", "note": "郑重许诺 won't let her", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 10, "en": "Hmm, you look happy. Man trouble?", "zh": "嗯，你看上去挺精神嘛。感情有烦恼了？", "note": "闺蜜八卦 Man trouble", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 11, "en": "Miguel is finished. It's all football with Miguel.", "zh": "米格尔彻底出局了。他满脑子除了足球还是足球。", "note": "潇洒放手 is finished", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 12, "en": "What do you expect from Spanish men?", "zh": "你还能指望西班牙男人怎样呢？", "note": "调侃吐槽 expect from", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 13, "en": "I'll never find a decent man. I'll just be single forever.", "zh": "我永远也碰不到靠谱好男人了，注定打一辈子光棍。", "note": "沮丧吐槽 single forever", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 14, "en": "What you need is a new man in your life.", "zh": "你真正需要的是在生活中开始一段崭新的恋情。", "note": "中肯建议 What you need", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 15, "en": "Nick is great as Pear Steele in London on Fire.", "zh": "尼克在《伦敦烽火》里演的皮尔·斯蒂尔太棒了。", "note": "角色赞美 great as", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 16, "en": "I want you to interview him for Stars at Nine.", "zh": "我想让你在《九点巨星》节目中对他做专访。", "note": "职场任务 interview", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 17, "en": "Interview Nick? That's all he talks about is girls and motorbikes.", "zh": "采访尼克？他嘴里除了女孩就是摩托车！", "note": "好友嫌弃 all he talks about", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 18, "en": "Ask him to take his jacket off.", "zh": "直接叫他把外套脱下来就行了。", "note": "直球建议 take off", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 19, "en": "It's all in a day's work for Nick.", "zh": "对尼克来说，这全都是家常便饭的小事一桩。", "note": "地道俚语 in a day's work", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 20, "en": "What are you reading? — A magazine about weddings.", "zh": "你在看什么呢？— 一本关于婚礼筹备的杂志。", "note": "日常闲聊 magazine", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 21, "en": "I love weddings, don't you?", "zh": "我最喜欢婚礼了，难道你不喜欢吗？", "note": "热情发问 don't you", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 22, "en": "Problem is, I'm always the bridesmaid, never the bride.", "zh": "问题是，我永远只是个伴娘，从来没当过新娘。", "note": "经典感叹 always the bridesmaid", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 23, "en": "Isn't it lovely? — The Ferrari? What a great car!", "zh": "是不是美极了？— 你说那辆法拉利？多帅的车啊！", "note": "男女关注点差异 Ferrari", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 24, "en": "I meant her dress. Do you like it, Nick?", "zh": "我说的是她的婚纱！你喜欢吗，尼克？", "note": "纠正误解 I meant", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 25, "en": "Well, it wouldn't suit me.", "zh": "呃，这穿在我身上可不太搭调吧。", "note": "幽默回避 wouldn't suit me", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 26, "en": "I love funny men. And good-looking ones.", "zh": "我喜欢风趣幽默的男人，还有长相帅气的。", "note": "择偶喜好 funny men", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 27, "en": "I'd love to marry a funny, good-looking man.", "zh": "我真想嫁给一个又帅又有幽默感的男人。", "note": "内心独白 love to marry", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 28, "en": "I saw London on Fire. You're very good in it.", "zh": "我看了《伦敦烽火》，你在里面的表演精彩极了。", "note": "当面称赞 very good in it", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 29, "en": "Will you do an interview with me for Channel 9?", "zh": "你愿意接受我和第9频道的电视专访吗？", "note": "发出专访邀请 interview", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 30, "en": "I really want a small wedding.", "zh": "我真的只想要一场简简单单的小型婚礼。", "note": "真实心愿 small wedding", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 31, "en": "Hector's mother keeps interfering. It's too much.", "zh": "赫克托的妈妈总是横加干涉，这实在让人吃不消。", "note": "烦恼倾诉 keeps interfering", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 32, "en": "I don't have any luck with men.", "zh": "我在男人缘这方面可真是一点运气都没有。", "note": "感叹自嘲 no luck with", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 33, "en": "I should just cancel the wedding.", "zh": "我干脆把这门婚事取消算了。", "note": "赌气念头 cancel wedding", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 34, "en": "I suppose marriage will mean sacrifices.", "zh": "我想，婚姻大概就意味着要做出很多牺牲吧。", "note": "婚前感悟 mean sacrifices", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 35, "en": "She's being very nice to me. — Well, maybe she is ill.", "zh": "她最近对我特别温柔。— 额，那她八成是病得不轻。", "note": "讽刺调侃 being very nice", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 36, "en": "You don't think she wants to get married too, do you?", "zh": "你该不会以为她也想结婚了吧，对不对？", "note": "推测询问 don't think", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 37, "en": "I fancy Nick. — But you don't like Nick!", "zh": "我有点看上尼克了。— 可你平时明明最看不惯他！", "note": "地道英俚 I fancy", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 38, "en": "You think he's an idiot. — Yes, but he's so macho!", "zh": "你嫌他是个大傻瓜。— 话是没错，但他太有男人味了！", "note": "反差吸引 macho", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 39, "en": "You think he's vain. — But he's so good-looking.", "zh": "你嫌他爱臭美虚荣。— 但他长得实在是太英俊了。", "note": "颜控本质 good-looking", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 40, "en": "It's one good thing about getting married: The stag night!", "zh": "结婚只有一件顶呱呱的好事：那就是单身汉狂欢之夜！", "note": "派对文化 stag night", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 41, "en": "Goodbye to your fantastic life as a single man!", "zh": "和你那潇洒自在、无拘无束的单身生活挥手告别吧！", "note": "告别单身 single man", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 42, "en": "Goodbye to drinking beer and watching football in bed.", "zh": "告别躺在床上喝啤酒、看球赛的神仙日子吧。", "note": "惬意时光 drinking beer", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 43, "en": "In England, we do crazy things. We party.", "zh": "在英国，我们可会玩各种疯狂的花样了，尽情派对狂欢！", "note": "文化分享 crazy things", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 44, "en": "Do you want to take your jacket off now? — No, not really.", "zh": "你现在想把夹克脱下来吗？— 额，其实并不想。", "note": "尴尬婉拒 not really", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 45, "en": "Annie, this wedding... — Okay, let's write it down.", "zh": "安妮，关于婚礼……— 好吧，我们各自写在纸上。", "note": "默契解决 write it down", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 46, "en": "Celebrate: not getting married!", "zh": "值得庆祝：我们用不着结婚受罪啦！", "note": "如释重负 Celebrate", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 47, "en": "Meet me at Leo's Cafe at 5 p.m.", "zh": "下午五点在利奥咖啡馆碰头见。", "note": "敲定时间地点 Meet me at", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 48, "en": "Thank goodness she's thousands of miles away in Argentina.", "zh": "谢天谢地，她还在数千里之外的阿根廷待着呢。", "note": "侥幸松口气 Thank goodness", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 49, "en": "Annie and I have decided to wait a few years before we get married.", "zh": "我和安妮商量好了，打算先推迟几年再考虑成家。", "note": "委婉拖延 wait a few years", "b64": "", "src": "extra"}, {"l": 113, "lt": "Extra E13 婚礼惊喜", "i": 50, "en": "Is he handsome? — Yes, he's very handsome and muscular.", "zh": "他人长得帅吗？— 是的，超级帅气，肌肉还特别结实。", "note": "外貌赞叹 handsome and muscular", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 1, "en": "Annie and Hector have decided not to get married.", "zh": "安妮和赫克托已经决定暂时不结婚了。", "note": "交待主线 not to get married", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 2, "en": "Bridget and Nick are dating, but Nick is getting bored.", "zh": "布里吉特和尼克开始约会了，但尼克开始觉得无聊了。", "note": "约会现状 getting bored", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 3, "en": "I just can't get enough. I want more, more, more.", "zh": "我简直欲罢不能，我还想要更多更多！", "note": "极度渴望 can't get enough", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 4, "en": "Nick, honey, there's plenty more where that came from.", "zh": "尼克亲爱的，这种好东西多得是，管够！", "note": "地道美语 plenty more", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 5, "en": "We've been together two days, Nick. — Wow, that long?", "zh": "我们俩在一起已经整整两天了，尼克。— 哇，居然有那么久啦？", "note": "幽默反差 that long", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 6, "en": "If we are to continue our relationship, you must treat me like a lady.", "zh": "如果我们要继续维持恋情，你必须像对待女士那样尊重我。", "note": "立规矩 treat me like a lady", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 7, "en": "Bridget, darling, just call me gentleman Nick.", "zh": "布里吉特亲爱的，以后直接叫我绅士尼克就行了。", "note": "嘴甜幽默 gentleman Nick", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 8, "en": "There must be more respect.", "zh": "人与人相处之间必须要有更多的尊重。", "note": "严肃态度 more respect", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 9, "en": "See what sort of gentleman you are. Here's a little test.", "zh": "来看看你算哪门子绅士。这里有个小小的考验。", "note": "绅士测试 little test", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 10, "en": "I want to go out. So, what do you do? — You open the door for me.", "zh": "我想出门。所以，你该怎么做？— 你要为我开门。", "note": "淑女礼仪 open the door", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 11, "en": "When other people see how important it is, they'll join us.", "zh": "当其他人意识到这有多重要时，他们就会加入我们的行列。", "note": "倡议号召 join us", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 12, "en": "No, no, no problem at all.", "zh": "没，完全没有任何问题。", "note": "口头掩饰 no problem at all", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 13, "en": "This is not fun. This is serious.", "zh": "这不是闹着玩的，这是极其严肃正经的事。", "note": "强调严肃 This is serious", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 14, "en": "Now, clothes. I want you more like David Beckham.", "zh": "现在来说穿搭。我希望你穿得更像大卫·贝克汉姆一些。", "note": "改造形象 David Beckham", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 15, "en": "Really, Bridget. I don't think... — Oh, don't be silly, Nick.", "zh": "真的吗布里吉特，我觉得……— 哎呀，别傻了尼克。", "note": "强势打断 don't be silly", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 16, "en": "You have a lot of anger there.", "zh": "你心里憋着好大一股无名火呢。", "note": "心理洞察 a lot of anger", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 17, "en": "Well, yes, I am wearing this stupid hair band.", "zh": "那可不，我还不是头上戴着这个蠢透了的发带。", "note": "搞笑自嘲 stupid hair band", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 18, "en": "So, we must work on your inner calm.", "zh": "所以，我们必须修炼你的内心平静。", "note": "修身养性 inner calm", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 19, "en": "Lie down. Close your eyes. And relax.", "zh": "躺下，闭上眼睛，全身放松。", "note": "冥想指令 relax", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 20, "en": "Now, this may tickle a bit. Ready? Here goes.", "zh": "好了，这可能会有一点点发痒。准备好了吗？开始咯。", "note": "打预防针 tickle a bit", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 21, "en": "Acupuncture never fails.", "zh": "针灸疗法向来是百试百灵。", "note": "传统疗法 Acupuncture", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 22, "en": "Sorry, I'm late. — Coffee? — Oh, yes, please.", "zh": "抱歉我迟到了。— 要来杯咖啡吗？— 噢太好了，麻烦来一杯。", "note": "礼貌日常 Coffee", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 23, "en": "Come on, Nick. I'm taking you shopping. And don't forget your money.", "zh": "走吧尼克，我带你去逛街购物。别忘了带上你的钱包。", "note": "霸道逛街 don't forget money", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 24, "en": "Bridget, at last, she realizes that I am the one for her.", "zh": "布里吉特终于开窍了，她终于意识到我才是她的真命天子。", "note": "沾沾自喜 I am the one", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 25, "en": "The only problem is she doesn't like my manners or my hair or my clothes.", "zh": "唯一的问题是：她既看不惯我的举止，也看不惯我的发型和衣品。", "note": "真实尴尬 only problem", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 26, "en": "I've been going out with Nick for two days now and he is perfect for me.", "zh": "我和尼克交往已经两天了，他对我来说简直完美无瑕。", "note": "闺蜜分享 perfect for me", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 27, "en": "Well, when I've changed him a bit, he will be perfect.", "zh": "呃，等我稍微把他改头换面调教一番之后，他就真的完美了。", "note": "女友改造计划 changed him", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 28, "en": "Mother, when in London, we speak English.", "zh": "妈妈，人在伦敦，我们就应该入乡随俗讲英语。", "note": "入乡随俗 speak English", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 29, "en": "English is a language of high class.", "zh": "英语可是极其优雅高贵的一门语言。", "note": "阶级偏见 high class", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 30, "en": "You must learn it, not teach it.", "zh": "你是要向别人学习英语，而不是去教别人。", "note": "纠正用词 learn not teach", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 31, "en": "Your father has found your wife. He must stop shopping on eBay.", "zh": "你爸已经替你物色好妻子了。— 他真该戒掉逛eBay网购的瘾了。", "note": "神级吐槽 shopping on eBay", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 32, "en": "Look, Mum, I don't want a wife. I've got money.", "zh": "听我说妈妈，我根本不急着娶妻，我又有钱。", "note": "表明态度 don't want a wife", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 33, "en": "This girl is rich. — I don't care about money.", "zh": "这个姑娘非常有钱。— 我才不在乎钱不钱的。", "note": "视金钱如粪土 don't care", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 34, "en": "Mum, Annie is my princess. She's so clever, so kind, so happy.", "zh": "妈妈，安妮就是我的公主。她冰雪聪明、心地善良、生性快乐。", "note": "深情维护 my princess", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 35, "en": "Now listen, Mum. I've told you I love Annie.", "zh": "好好听着妈妈，我明确告诉过你：我爱安妮！", "note": "坚定立场 I love Annie", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 36, "en": "If you knew Annie, you would love her.", "zh": "如果你真正了解安妮的为人，你肯定也会喜欢她的。", "note": "真诚恳求 If you knew", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 37, "en": "Come to dinner tonight, and you will meet the real Annie.", "zh": "今晚过来吃顿晚饭吧，你会见到真正真实可爱的安妮。", "note": "家宴邀约 meet the real Annie", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 38, "en": "Can we talk? — If that's okay with your mother.", "zh": "我们能谈谈吗？— 如果你妈妈不介意的话。", "note": "女友吃醋 Can we talk", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 39, "en": "Stay and be nice to her. She's okay, really.", "zh": "留下来对她友善客气点嘛，她人其实挺好的。", "note": "从中调和 be nice to her", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 40, "en": "Nick is pretending to be someone different.", "zh": "尼克都在假装扮演一个完全不同的人。", "note": "伪装表现 pretending", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 41, "en": "You can pretend to be what my mother wants: Princess Caroline of Monaco.", "zh": "你也可以假装成我妈妈心仪的那类人：比如摩纳哥卡洛琳公主。", "note": "荒唐建议 pretend to be", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 42, "en": "Nick is pretending to be what Bridget wants: Yeah, a slave!", "zh": "尼克正努力装成布里吉特想要的人：哈，那就是当奴隶！", "note": "神吐槽 slave", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 43, "en": "What sort of food does your mother like? Babies on toast?", "zh": "你妈妈喜欢吃什么口味的菜肴？难道是烤吐司夹婴儿吗？", "note": "荒诞毒舌 on toast", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 44, "en": "Nick, behave!", "zh": "尼克，老实点/规矩点！", "note": "严厉呵斥 behave", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 45, "en": "Tonight I will pretend to be the perfect girlfriend.", "zh": "今晚我就为了你，勉为其难演一回无可挑剔的完美女友。", "note": "妥协答应 perfect girlfriend", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 46, "en": "Have you enjoyed your visit to London, Mrs. Romero?", "zh": "罗梅罗太太，您这次伦敦之行过得还算开心吗？", "note": "客套寒暄 enjoyed your visit", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 47, "en": "Where do you learn your beautiful manners? — I was born with them.", "zh": "你这优雅得体的贵族礼仪是从哪儿学来的？— 我打娘胎里天生就自带的。", "note": "满分装腔 born with them", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 48, "en": "I love animals, but I don't eat them. I'm a vegetarian.", "zh": "我很爱小动物，但我可不吃它们。我是个素食主义者。", "note": "饮食习惯 vegetarian", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 49, "en": "If we cannot eat animals, why are they made of meat then?", "zh": "如果我们不能吃动物，那为什么它们偏偏全是由肉做成的呢？", "note": "神逻辑质问 made of meat", "b64": "", "src": "extra"}, {"l": 114, "lt": "Extra E14 生活变迁", "i": 50, "en": "That went rather well, didn't it?", "zh": "刚才那顿晚饭进展得还真挺顺利的，不是吗？", "note": "反讽调侃 rather well", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 1, "en": "Nick is desperate for a job. Any job.", "zh": "尼克极度渴望找到一份工作，随便什么工作都行。", "note": "急需工作 desperate for", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 2, "en": "Now stay still. You will just feel a little needle prick.", "zh": "现在别乱动，你只会感觉到像被小针轻轻扎了一下。", "note": "打预防针 stay still", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 3, "en": "Are you scared of needles? — Who? Me? Don't be silly.", "zh": "你该不会是害怕针头吧？— 谁？我吗？别傻了。", "note": "嘴硬否认 scared of needles", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 4, "en": "If you're not scared of needles, would you have a tattoo?", "zh": "如果你真不怕针，那你敢去纹身吗？", "note": "激将法 tattoo", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 5, "en": "Go on then, tough guy. — Okay, I'll have one if you have one.", "zh": "来啊硬汉。— 行啊，你要敢纹我就敢纹。", "note": "打赌 deal", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 6, "en": "Okay, okay. It's a deal. A deal is a deal, isn't it?", "zh": "成交！一言为定，说话要算话，对吧？", "note": "一言为定 It's a deal", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 7, "en": "I want a word with you. Tough guy, eh? What do you want?", "zh": "我想跟你谈谈。硬汉是吧？你想要怎样？", "note": "找茬挑衅 want a word", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 8, "en": "I don't like your face.", "zh": "我看你这张脸很不顺眼。", "note": "保镖挑衅经典台词 don't like your face", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 9, "en": "Guys, you are looking at muscles! — Where?", "zh": "伙计们，你们现在眼前看到的是肌肉！— 哪儿呢？", "note": "幽默互怼 muscles", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 10, "en": "I am the new man on the door at ICE.", "zh": "我是ICE夜店新来的看门保镖。", "note": "新职位 on the door", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 11, "en": "What? You're a bouncer? — What is a bouncer?", "zh": "什么？你成了保镖？— 什么是bouncer？", "note": "词汇科普 bouncer", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 12, "en": "It's someone who throws people out of nightclubs.", "zh": "就是专门负责把闹事者扔出夜店的人。", "note": "解释职业 throws people out", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 13, "en": "I am an entry executive.", "zh": "我是“入场执行官”（把看门说得高大上）。", "note": "幽默职场头衔 executive", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 14, "en": "Nick, granny could beat you up.", "zh": "尼克，就连老奶奶都能把你打得落花流水。", "note": "吐槽武力 beat you up", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 15, "en": "Has someone died? — No, not yet. Why are you dressed in black, then?", "zh": "家里谁去世了吗？— 还没呢。那你干嘛一身黑衣打扮？", "note": "日常毒舌 dressed in black", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 16, "en": "If your name's not on the guest list, then you can't come in.", "zh": "如果你的名字不在贵宾名单上，那你就休想进门。", "note": "金句 guest list", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 17, "en": "Nick, if my name's not on the guest list, then you can't come home.", "zh": "尼克，要是我名字不在名单上，那你今晚就别想进家门！", "note": "女友霸气反制 can't come home", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 18, "en": "Guess what? I've got a new job. I'm a bouncer at ICE.", "zh": "猜猜怎么着？我找着新工作了，我是ICE的保镖！", "note": "宣布喜讯 Guess what", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 19, "en": "This club is very trendy, very exclusive.", "zh": "这家俱乐部非常时髦前卫，极其高端排外。", "note": "高端场所 trendy and exclusive", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 20, "en": "When the girls see me on the door, they won't want to go in.", "zh": "当姑娘们在门口看到我时，她们都迷得舍不得进去了。", "note": "自恋狂妄 won't want to go in", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 21, "en": "If he doesn't get me on the guest list, he is in big trouble.", "zh": "要是他没把我弄进贵宾名单，他可就有大麻烦了。", "note": "放狠话 in big trouble", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 22, "en": "I just wondered if you wanted to share my chocolate with me.", "zh": "我只是想问问你，愿不愿在布里吉特发现之前跟我分着吃巧克力。", "note": "偷吃零食 share chocolate", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 23, "en": "Honey, do you think I should be more macho?", "zh": "亲爱的，你觉得我是不是应该更有男人味/硬汉一点？", "note": "探讨男子气概 more macho", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 24, "en": "You don't have to be a tough guy for me. I love you just the way you are.", "zh": "你不需要为了我装成什么硬汉，我就喜欢你现在的样子。", "note": "经典告白 just the way you are", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 25, "en": "You're so strong! — Oh, what is it? — You are standing on my foot.", "zh": "你力气好大啊！— 怎么了？— 你踩到我的脚了！", "note": "搞笑转折 standing on my foot", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 26, "en": "Honey, just call me a wimp.", "zh": "亲爱的，她刚才分明就是在叫我懦夫/软蛋。", "note": "委屈抱怨 wimp", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 27, "en": "I want to be a tough guy like you. Can you teach me?", "zh": "我也想像你一样当个硬汉，你能教教我吗？", "note": "拜师求学 tough guy", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 28, "en": "Why don't you show me how to be a bouncer?", "zh": "你何不示范一下怎样才能当好一名保镖？", "note": "请教技巧 how to be a bouncer", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 29, "en": "Are you looking at me? Are you looking at me?", "zh": "你瞅啥？你刚才是在看我吗？", "note": "保镖经典狠话 Are you looking at me", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 30, "en": "So who am I looking at when I say that? — Anyone who is looking for trouble!", "zh": "那我冲着谁说这句话？— 任何存心找茬惹事的人！", "note": "挑衅应对 looking for trouble", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 31, "en": "And how do I know they are looking for trouble? — You just know.", "zh": "那怎么才能看出他们是来找茬的？— 凭直觉你自然就知道。", "note": "保镖直觉 You just know", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 32, "en": "You cannot come in. — Let me in.", "zh": "你不能进去。— 快放我进去！", "note": "门口阻拦 cannot come in", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 33, "en": "Are you looking at me or chewing a brick?", "zh": "你是在瞪我呢，还是在啃砖头？", "note": "经典狠话 chewing a brick", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 34, "en": "Because either way, you lose your teeth!", "zh": "因为不管哪样，你的牙齿今天都保不住了！", "note": "霸气恐吓 lose your teeth", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 35, "en": "You are a very scary guy.", "zh": "你可真是一个让人心惊胆战的可怕狠人。", "note": "夸赞气场 very scary", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 36, "en": "Hello, you are looking lovely tonight.", "zh": "嗨，几位今晚看起来真是迷人极了。", "note": "对美女献殷勤 looking lovely", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 37, "en": "Please, could I have your name, sir?", "zh": "先生，请问能出示报一下您的姓名吗？", "note": "礼貌查名 have your name", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 38, "en": "What do you want that for?", "zh": "你要我名字干什么用？", "note": "不耐烦反问 What do you want that for", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 39, "en": "Of course, I had the situation completely under control.", "zh": "当然了，整个局势完全都在我的掌控之中。", "note": "吹嘘控场 completely under control", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 40, "en": "So, Bridget, why are you here? — I brought you some sandwiches.", "zh": "话说布里吉特，你怎么会来这儿？— 我给你带了些三明治。", "note": "送餐探班 brought you sandwiches", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 41, "en": "I'm afraid I can't tell you. It's confidential.", "zh": "恐怕我不能透露给你，这属于内部机密。", "note": "装模作样 It's confidential", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 42, "en": "Sorry, Bridget. I have work to do.", "zh": "不好意思布里吉特，我还有正经工作要忙。", "note": "公事公办 have work to do", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 43, "en": "Good evening, ladies. Could I have your names, please?", "zh": "晚上好，女士们。能请教一下各位的芳名吗？", "note": "查验身份 have your names", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 44, "en": "Thank you very much, ladies. Have a great evening.", "zh": "非常感谢，女士们，祝你们度过一个美妙的夜晚。", "note": "绅士送入 Have a great evening", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 45, "en": "All part of the job.", "zh": "这全都是我份内的工作职责。", "note": "职场自得 All part of the job", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 46, "en": "As soon as I can arrange it, I will.", "zh": "只要我能安排妥当，我一定会替你办好。", "note": "做出承诺 As soon as I can", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 47, "en": "Look, there's a big Latino night next week. JLo will be coming.", "zh": "听着，下周有个大型拉丁狂欢夜，詹妮弗·洛佩兹也会来。", "note": "大咖造势 Latino night", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 48, "en": "Leave it to me.", "zh": "包在我身上，交给我来办！", "note": "大包大揽 Leave it to me", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 49, "en": "Hector has had a tattoo done just for me. Isn't it romantic?", "zh": "赫克托专门为我纹了一个纹身，是不是超级浪漫？", "note": "炫耀恩爱 Isn't it romantic", "b64": "", "src": "extra"}, {"l": 115, "lt": "Extra E15 俱乐部保镖", "i": 50, "en": "It's coming off! Farley has licked it off. It's a fake!", "zh": "纹身掉色了！小狗法利舔一下就没了，这是个假纹身！", "note": "当场穿帮 It's a fake", "b64": "", "src": "extra"}];
